// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for string_escape_mem() from lib/string_helpers.c.
 */

#include <kunit/test.h>
#include <linux/ctype.h>
#include <linux/module.h>
#include <linux/string.h>
#include <linux/string_helpers.h>
#include <linux/types.h>

#define CANARY		0xA5
#define GUARD		8

/*
 * Core checker. For a given input/flags/only it verifies that:
 *  - a NULL destination with osz == 0 returns the full escaped size,
 *  - with osz == strlen(exp) the output matches @exp exactly and nothing
 *    is written past the buffer,
 *  - for every osz in [0, strlen(exp)) the function still returns the full
 *    size, writes exactly the first osz bytes, and touches nothing beyond,
 *  - with a larger osz nothing is written past the escaped size.
 */
static void check_escape(struct kunit *test, const char *src, size_t isz,
			 unsigned int flags, const char *only, const char *exp,
			 size_t explen)
{
	size_t bufsz = explen + GUARD;
	char *buf;
	size_t osz, i;
	int ret;

	buf = kunit_kmalloc(test, bufsz, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, buf);

	/* Sizing call: NULL dst, zero osz. */
	ret = string_escape_mem(src, isz, NULL, 0, flags, only);
	KUNIT_EXPECT_EQ_MSG(test, ret, (int)explen,
			    "sizing call: flags=%#x only=%s exp=\"%s\"",
			    flags, only ? only : "(null)", exp);

	/* Exact-size buffer. */
	memset(buf, CANARY, bufsz);
	ret = string_escape_mem(src, isz, buf, explen, flags, only);
	KUNIT_EXPECT_EQ(test, ret, (int)explen);
	KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, exp, explen), 0,
			    "exact-size output mismatch, exp=\"%s\"", exp);
	for (i = explen; i < bufsz; i++)
		KUNIT_EXPECT_EQ_MSG(test, (unsigned char)buf[i], CANARY,
				    "overrun at %zu (osz=%zu, exp=\"%s\")",
				    i, explen, exp);

	/* Every truncating size, including zero. */
	for (osz = 0; osz < explen; osz++) {
		memset(buf, CANARY, bufsz);
		ret = string_escape_mem(src, isz, buf, osz, flags, only);
		KUNIT_EXPECT_EQ_MSG(test, ret, (int)explen,
				    "truncated return osz=%zu exp=\"%s\"",
				    osz, exp);
		KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, exp, osz), 0,
				    "truncated prefix mismatch osz=%zu exp=\"%s\"",
				    osz, exp);
		for (i = osz; i < bufsz; i++)
			KUNIT_EXPECT_EQ_MSG(test, (unsigned char)buf[i],
					    CANARY,
					    "overrun at %zu (osz=%zu, exp=\"%s\")",
					    i, osz, exp);
	}

	/* Oversized buffer: no terminator, no writes past explen. */
	memset(buf, CANARY, bufsz);
	ret = string_escape_mem(src, isz, buf, bufsz, flags, only);
	KUNIT_EXPECT_EQ(test, ret, (int)explen);
	KUNIT_EXPECT_EQ(test, memcmp(buf, exp, explen), 0);
	for (i = explen; i < bufsz; i++)
		KUNIT_EXPECT_EQ_MSG(test, (unsigned char)buf[i], CANARY,
				    "oversized buffer written at %zu", i);

	kunit_kfree(test, buf);
}

/* @src and @exp are string literals; embedded NUL bytes are handled. */
#define CHECK_STR(test, src, flags, only, exp) \
	check_escape(test, src, sizeof(src) - 1, flags, only, exp, \
		     sizeof(exp) - 1)
#define CHECK_MEM(test, src, isz, flags, only, exp) \
	check_escape(test, src, isz, flags, only, exp, sizeof(exp) - 1)

/* ---- normal inputs ---------------------------------------------------- */

static void agent_test_empty_input(struct kunit *test)
{
	char buf[4] = { CANARY, CANARY, CANARY, CANARY };
	int ret;

	ret = string_escape_mem("abc", 0, buf, sizeof(buf), ESCAPE_ANY_NP, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[0], CANARY);

	ret = string_escape_mem("abc", 0, NULL, 0, ESCAPE_ANY_NP, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);

	ret = string_escape_mem("", 0, buf, 0, 0, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
}

static void agent_test_no_flags_passthrough(struct kunit *test)
{
	/* With no flags every byte, including NUL and non-ASCII, is copied. */
	static const char src[] = "a\n\0\\\"\x7f\x80\xff z";

	CHECK_STR(test, src, 0, NULL, "a\n\0\\\"\x7f\x80\xff z");
	CHECK_STR(test, src, ESCAPE_NP | ESCAPE_NA | ESCAPE_NAP, NULL,
		  "a\n\0\\\"\x7f\x80\xff z");
}

static void agent_test_isz_is_honoured(struct kunit *test)
{
	/* Only the first isz bytes are processed, regardless of NULs. */
	static const char src[] = "ab\0cd";
	char buf[16];
	int ret;

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem(src, 5, buf, sizeof(buf), ESCAPE_NULL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 6);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "ab\\0cd", 6), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[6], CANARY);

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem(src, 2, buf, sizeof(buf), ESCAPE_NULL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "ab", 2), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[2], CANARY);

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem(src, 1, buf, sizeof(buf), ESCAPE_NULL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 1);
	KUNIT_EXPECT_EQ(test, buf[0], 'a');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[1], CANARY);
}

static void agent_test_escape_space(struct kunit *test)
{
	CHECK_STR(test, "\n", ESCAPE_SPACE, NULL, "\\n");
	CHECK_STR(test, "\r", ESCAPE_SPACE, NULL, "\\r");
	CHECK_STR(test, "\t", ESCAPE_SPACE, NULL, "\\t");
	CHECK_STR(test, "\v", ESCAPE_SPACE, NULL, "\\v");
	CHECK_STR(test, "\f", ESCAPE_SPACE, NULL, "\\f");
	CHECK_STR(test, "a\nb\rc\td\ve\ff", ESCAPE_SPACE, NULL,
		  "a\\nb\\rc\\td\\ve\\ff");
	/* Space itself and SPECIAL/NULL classes are not touched. */
	CHECK_STR(test, " ", ESCAPE_SPACE, NULL, " ");
	CHECK_STR(test, "\\\"\a\e", ESCAPE_SPACE, NULL, "\\\"\a\e");
	CHECK_STR(test, "\x0e\x08\x7f", ESCAPE_SPACE, NULL, "\x0e\x08\x7f");
	/* NUL is not a SPACE-class char: copied raw. */
	CHECK_MEM(test, "\0", 1, ESCAPE_SPACE, NULL, "\0");
}

static void agent_test_escape_special(struct kunit *test)
{
	CHECK_STR(test, "\\", ESCAPE_SPECIAL, NULL, "\\\\");
	CHECK_STR(test, "\"", ESCAPE_SPECIAL, NULL, "\\\"");
	CHECK_STR(test, "\a", ESCAPE_SPECIAL, NULL, "\\a");
	CHECK_STR(test, "\e", ESCAPE_SPECIAL, NULL, "\\e");
	CHECK_STR(test, "x\\y\"z\aw\e", ESCAPE_SPECIAL, NULL,
		  "x\\\\y\\\"z\\aw\\e");
	/* SPACE class and single quote are not touched. */
	CHECK_STR(test, "\n\t'", ESCAPE_SPECIAL, NULL, "\n\t'");
	/* Neighbours of the escape char (0x1a, 0x1c) are not touched. */
	CHECK_STR(test, "\x1a\x1c\x06\x08", ESCAPE_SPECIAL, NULL,
		  "\x1a\x1c\x06\x08");
}

static void agent_test_escape_null(struct kunit *test)
{
	CHECK_MEM(test, "\0", 1, ESCAPE_NULL, NULL, "\\0");
	CHECK_MEM(test, "a\0b\0", 4, ESCAPE_NULL, NULL, "a\\0b\\0");
	/* Only the NUL byte, not '0' or 0x01. */
	CHECK_STR(test, "0\x01", ESCAPE_NULL, NULL, "0\x01");
	CHECK_STR(test, "\n\\", ESCAPE_NULL, NULL, "\n\\");
}

static void agent_test_escape_octal_all_bytes(struct kunit *test)
{
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char src = c;
		char exp[5];

		snprintf(exp, sizeof(exp), "\\%03o", c);
		check_escape(test, &src, 1, ESCAPE_OCTAL, NULL, exp, 4);
	}
}

static void agent_test_escape_hex_all_bytes(struct kunit *test)
{
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char src = c;
		char exp[5];

		snprintf(exp, sizeof(exp), "\\x%02x", c);
		check_escape(test, &src, 1, ESCAPE_HEX, NULL, exp, 4);
	}
}

static void agent_test_octal_and_hex_multi(struct kunit *test)
{
	CHECK_STR(test, "\x01\x7f\x80\xff", ESCAPE_OCTAL, NULL,
		  "\\001\\177\\200\\377");
	CHECK_STR(test, "\x01\x7f\x80\xff", ESCAPE_HEX, NULL,
		  "\\x01\\x7f\\x80\\xff");
	/* OCTAL wins over HEX when both are set. */
	CHECK_STR(test, "A\xab", ESCAPE_OCTAL | ESCAPE_HEX, NULL,
		  "\\101\\253");
	/* Hex digits are lower case. */
	CHECK_STR(test, "\xab\xcd\xef", ESCAPE_HEX, NULL,
		  "\\xab\\xcd\\xef");
}

static void agent_test_escape_any(struct kunit *test)
{
	CHECK_MEM(test, "\n\\\0\x01", 4, ESCAPE_ANY, NULL,
		     "\\n\\\\\\0\\001");
	/* ESCAPE_ANY escapes printable characters via octal as well. */
	CHECK_STR(test, "A ~", ESCAPE_ANY, NULL, "\\101\\040\\176");
}

/* ---- class precedence -------------------------------------------------- */

static void agent_test_precedence(struct kunit *test)
{
	/* SPACE beats OCTAL/HEX. */
	CHECK_STR(test, "\n", ESCAPE_SPACE | ESCAPE_OCTAL, NULL, "\\n");
	CHECK_STR(test, "\n", ESCAPE_SPACE | ESCAPE_HEX, NULL, "\\n");
	/* SPECIAL beats OCTAL/HEX. */
	CHECK_STR(test, "\\", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\\\");
	CHECK_STR(test, "\e", ESCAPE_SPECIAL | ESCAPE_HEX, NULL, "\\e");
	/* NULL beats OCTAL/HEX. */
	CHECK_MEM(test, "\0", 1, ESCAPE_NULL | ESCAPE_OCTAL, NULL, "\\0");
	CHECK_MEM(test, "\0", 1, ESCAPE_NULL | ESCAPE_HEX, NULL, "\\0");
	/* Without NULL class, NUL falls to OCTAL/HEX. */
	CHECK_MEM(test, "\0", 1, ESCAPE_SPACE | ESCAPE_OCTAL, NULL, "\\000");
	CHECK_MEM(test, "\0", 1, ESCAPE_HEX, NULL, "\\x00");
	/* Without SPACE class, newline falls to OCTAL. */
	CHECK_STR(test, "\n", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\012");
	/* Without SPECIAL class, backslash falls to HEX. */
	CHECK_STR(test, "\\", ESCAPE_SPACE | ESCAPE_HEX, NULL, "\\x5c");
}

/* ---- NP / NA / NAP ----------------------------------------------------- */

static void agent_test_escape_np(struct kunit *test)
{
	/* NP alone escapes nothing: no class to escape with. */
	CHECK_STR(test, "\x01\n\x7f\x80 A~", ESCAPE_NP, NULL,
		  "\x01\n\x7f\x80 A~");

	/* Printable range boundaries: 0x1f escaped, 0x20 and 0x7e pass, 0x7f escaped. */
	CHECK_STR(test, "\x1f", ESCAPE_NP | ESCAPE_OCTAL, NULL, "\\037");
	CHECK_STR(test, " ", ESCAPE_NP | ESCAPE_OCTAL, NULL, " ");
	CHECK_STR(test, "~", ESCAPE_NP | ESCAPE_OCTAL, NULL, "~");
	CHECK_STR(test, "\x7f", ESCAPE_NP | ESCAPE_OCTAL, NULL, "\\177");
	/* 0x80..0x9f are non-printable in the kernel ctype table. */
	CHECK_STR(test, "\x80\x9f", ESCAPE_NP | ESCAPE_HEX, NULL,
		  "\\x80\\x9f");
	/* 0xa0..0xff are printable in the kernel ctype table. */
	CHECK_STR(test, "\xa0\xff", ESCAPE_NP | ESCAPE_HEX, NULL,
		  "\xa0\xff");

	/* Printable SPECIAL chars pass through under NP, non-printable SPACE escaped. */
	CHECK_STR(test, "\\\"", ESCAPE_NP | ESCAPE_SPECIAL | ESCAPE_OCTAL,
		  NULL, "\\\"");
	CHECK_STR(test, "\n\a", ESCAPE_NP | ESCAPE_SPACE | ESCAPE_OCTAL,
		  NULL, "\\n\\007");

	CHECK_MEM(test, "\0", 1, ESCAPE_NP | ESCAPE_NULL, NULL, "\\0");
	CHECK_MEM(test, "a\0b", 3, ESCAPE_ANY_NP, NULL, "a\\0b");
	CHECK_STR(test, "Hi\tthere\x01!", ESCAPE_ANY_NP, NULL,
		  "Hi\\tthere\\001!");
}

static void agent_test_escape_na(struct kunit *test)
{
	/* ASCII (including non-printable and 0x7f) passes through. */
	CHECK_STR(test, "\x01\n\x7f A", ESCAPE_NA | ESCAPE_OCTAL, NULL,
		  "\x01\n\x7f A");
	/* NUL is ASCII, so it passes through raw under NA. */
	CHECK_MEM(test, "\0", 1, ESCAPE_NA | ESCAPE_OCTAL, NULL, "\0");
	/* First non-ASCII byte is escaped. */
	CHECK_STR(test, "\x7f\x80", ESCAPE_NA | ESCAPE_OCTAL, NULL,
		  "\x7f\\200");
	CHECK_STR(test, "\x80\xa0\xff", ESCAPE_NA | ESCAPE_HEX, NULL,
		  "\\x80\\xa0\\xff");
	/* NA with SPACE/SPECIAL: ASCII still passes before those classes. */
	CHECK_STR(test, "\n\\", ESCAPE_NA | ESCAPE_SPACE | ESCAPE_SPECIAL,
		  NULL, "\n\\");
	/* NA alone, nothing to escape with. */
	CHECK_STR(test, "\x80", ESCAPE_NA, NULL, "\x80");
}

static void agent_test_escape_nap(struct kunit *test)
{
	/* Printable ASCII passes through. */
	CHECK_STR(test, " A~", ESCAPE_NAP | ESCAPE_OCTAL, NULL, " A~");
	/* Non-printable ASCII escaped. */
	CHECK_STR(test, "\x1f\x7f", ESCAPE_NAP | ESCAPE_OCTAL, NULL,
		  "\\037\\177");
	/* Non-ASCII escaped even if ctype says printable. */
	CHECK_STR(test, "\x80\xa0\xff", ESCAPE_NAP | ESCAPE_HEX, NULL,
		  "\\x80\\xa0\\xff");
	/* NAP with SPACE/SPECIAL uses those classes for non-printables. */
	CHECK_STR(test, "\n\a\"", ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_SPECIAL |
		  ESCAPE_OCTAL, NULL, "\\n\\a\"");
	CHECK_MEM(test, "\0", 1, ESCAPE_NAP | ESCAPE_NULL, NULL, "\\0");
	/* NAP alone, nothing to escape with. */
	CHECK_STR(test, "\x01\x80", ESCAPE_NAP, NULL, "\x01\x80");
}

static void agent_test_np_na_nap_full_range(struct kunit *test)
{
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char src = c;
		char exp[5];
		bool asc = c < 0x80;
		bool prt = isprint(c);

		/* NP */
		if (prt)
			snprintf(exp, sizeof(exp), "%c", c);
		else
			snprintf(exp, sizeof(exp), "\\x%02x", c);
		check_escape(test, &src, 1, ESCAPE_NP | ESCAPE_HEX, NULL, exp,
			     strlen(exp));

		/* NA */
		if (asc)
			snprintf(exp, sizeof(exp), "%c", c);
		else
			snprintf(exp, sizeof(exp), "\\x%02x", c);
		if (c == 0)
			CHECK_MEM(test, &src, 1, ESCAPE_NA | ESCAPE_HEX, NULL, "\0");
		else
			check_escape(test, &src, 1, ESCAPE_NA | ESCAPE_HEX, NULL,
				     exp, strlen(exp));

		/* NAP */
		if (asc && prt)
			snprintf(exp, sizeof(exp), "%c", c);
		else
			snprintf(exp, sizeof(exp), "\\x%02x", c);
		check_escape(test, &src, 1, ESCAPE_NAP | ESCAPE_HEX, NULL, exp,
			     strlen(exp));
	}
}

/* ---- @only dictionary -------------------------------------------------- */

static void agent_test_only_dict(struct kunit *test)
{
	/* Characters not in @only pass through regardless of class. */
	CHECK_STR(test, "\n\t\\", ESCAPE_ANY, "\n", "\\n\t\\");
	CHECK_STR(test, "\n\t\\", ESCAPE_ANY, "\t\\", "\n\\t\\\\");
	CHECK_STR(test, "abc", ESCAPE_OCTAL, "b", "a\\142c");
	CHECK_STR(test, "abc", ESCAPE_HEX, "ac", "\\x61b\\x63");
	/* Character in @only but not in any selected class is copied as-is. */
	CHECK_STR(test, "a\n", ESCAPE_SPECIAL, "a\n", "a\n");
	/* Nothing in @only matches: identity. */
	CHECK_STR(test, "\x01\x02", ESCAPE_ANY, "xyz", "\x01\x02");
}

static void agent_test_only_null_and_empty(struct kunit *test)
{
	/* NULL and "" are equivalent: no dictionary. */
	CHECK_STR(test, "a\n\x01", ESCAPE_ANY_NP, NULL, "a\\n\\001");
	CHECK_STR(test, "a\n\x01", ESCAPE_ANY_NP, "", "a\\n\\001");
	CHECK_STR(test, "\x80", ESCAPE_HEX, "", "\\x80");
	CHECK_STR(test, "\x80", ESCAPE_HEX, NULL, "\\x80");
}

static void agent_test_only_with_np(struct kunit *test)
{
	/* @only restricts, NP still lets printable chars through. */
	CHECK_STR(test, "a\n\x01", ESCAPE_ANY_NP, "a\n", "a\\n\x01");
	CHECK_STR(test, "a\n\x01", ESCAPE_ANY_NP, "\x01", "a\n\\001");
	/* Non-printable not in @only passes even under NP + OCTAL. */
	CHECK_STR(test, "\x01\x02", ESCAPE_NP | ESCAPE_OCTAL, "\x02",
		  "\x01\\002");
}

static void agent_test_only_nul_byte_quirk(struct kunit *test)
{
	/*
	 * strchr(only, '\0') finds the terminator, so a NUL byte is always
	 * considered part of a non-empty @only and gets escaped by its class.
	 */
	CHECK_MEM(test, "\0", 1, ESCAPE_NULL, "a", "\\0");
	CHECK_MEM(test, "\0", 1, ESCAPE_OCTAL, "zz", "\\000");
	CHECK_MEM(test, "x\0y", 3, ESCAPE_ANY, "q", "x\\0y");
}

/* ---- ESCAPE_APPEND ----------------------------------------------------- */

static void agent_test_append_with_np(struct kunit *test)
{
	/* Printable chars listed in @only are escaped despite NP. */
	CHECK_STR(test, "abc", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_OCTAL, "b",
		  "a\\142c");
	CHECK_STR(test, "a\x01" "b", ESCAPE_ANY_NP | ESCAPE_APPEND, "b",
		  "a\\001\\142");
	/* Chars not in @only still follow NP rules (non-printables escaped). */
	CHECK_STR(test, "\x01" "a", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_HEX, "z",
		  "\\x01" "a");
	/* Listed char that has no class is still passed through. */
	CHECK_STR(test, "ab", ESCAPE_NP | ESCAPE_APPEND, "b", "ab");
	/* Listed char falls into SPECIAL class when selected. */
	CHECK_STR(test, "\"", ESCAPE_NP | ESCAPE_APPEND | ESCAPE_SPECIAL, "\"",
		  "\\\"");
}

static void agent_test_append_with_na_nap(struct kunit *test)
{
	/* NA: ASCII chars in @only are escaped. */
	CHECK_STR(test, "A\x80" "B", ESCAPE_NA | ESCAPE_APPEND | ESCAPE_HEX, "B",
		  "A\\x80\\x42");
	/* NAP: printable ASCII in @only is escaped. */
	CHECK_STR(test, " !", ESCAPE_NAP | ESCAPE_APPEND | ESCAPE_OCTAL, " ",
		  "\\040!");
	/* Non-ASCII not in @only still escaped under NA/NAP. */
	CHECK_STR(test, "\xff", ESCAPE_NAP | ESCAPE_APPEND | ESCAPE_OCTAL, "q",
		  "\\377");
}

static void agent_test_append_without_np(struct kunit *test)
{
	/*
	 * With ESCAPE_APPEND the "@only does not contain char" short-circuit
	 * is disabled, so characters outside @only are escaped by class too.
	 */
	CHECK_STR(test, "ab", ESCAPE_APPEND | ESCAPE_OCTAL, "a", "\\141\\142");
	CHECK_STR(test, "\n\t", ESCAPE_APPEND | ESCAPE_SPACE, "\n", "\\n\\t");
	/* Compare: same without APPEND leaves 'b' / '\t' untouched. */
	CHECK_STR(test, "ab", ESCAPE_OCTAL, "a", "\\141b");
	CHECK_STR(test, "\n\t", ESCAPE_SPACE, "\n", "\\n\t");
	/* APPEND with no dictionary behaves like no APPEND. */
	CHECK_STR(test, "a\x01", ESCAPE_ANY_NP | ESCAPE_APPEND, NULL, "a\\001");
	CHECK_STR(test, "a\x01", ESCAPE_ANY_NP | ESCAPE_APPEND, "", "a\\001");
}

/* ---- boundaries: output sizing ---------------------------------------- */

static void agent_test_osz_boundaries(struct kunit *test)
{
	/* "\x01" -> "\\001": 4 output bytes from 1 input byte. */
	char buf[8];
	int ret;
	size_t osz, i;

	for (osz = 0; osz <= 6; osz++) {
		memset(buf, CANARY, sizeof(buf));
		ret = string_escape_mem("\x01", 1, buf, osz, ESCAPE_OCTAL, NULL);
		KUNIT_EXPECT_EQ_MSG(test, ret, 4, "osz=%zu", osz);
		KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, "\\001", min_t(size_t, osz, 4)),
				    0, "osz=%zu", osz);
		for (i = min_t(size_t, osz, 4); i < sizeof(buf); i++)
			KUNIT_EXPECT_EQ_MSG(test, (unsigned char)buf[i], CANARY,
					    "osz=%zu i=%zu", osz, i);
	}

	/* Truncation inside a 2-byte escape: only the backslash is written. */
	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem("a\n", 2, buf, 2, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_EQ(test, buf[0], 'a');
	KUNIT_EXPECT_EQ(test, buf[1], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[2], CANARY);

	/* Truncation inside a hex escape after the 'x'. */
	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem("\xab", 1, buf, 3, ESCAPE_HEX, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "\\xa", 3), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[3], CANARY);
}

static void agent_test_return_counts_all_escapes(struct kunit *test)
{
	/* Mixed input exercising every class; verify total size arithmetic. */
	static const char src[] = "p\n\\\0\x01\x80~";
	size_t isz = sizeof(src) - 1;
	int ret;

	/* 1 + 2 + 2 + 2 + 4 + 4 + 1 = 16 */
	ret = string_escape_mem(src, isz, NULL, 0, ESCAPE_ANY_NP, NULL);
	KUNIT_EXPECT_EQ(test, ret, 16);
	CHECK_MEM(test, src, isz, ESCAPE_ANY_NP, NULL,
		  "p\\n\\\\\\0\\001\\200~");

	/* All octal: 7 * 4 = 28 */
	ret = string_escape_mem(src, isz, NULL, 0, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, 28);

	/* Nothing: 7 */
	ret = string_escape_mem(src, isz, NULL, 0, 0, NULL);
	KUNIT_EXPECT_EQ(test, ret, 7);
}

static void agent_test_long_input(struct kunit *test)
{
	/* 256 bytes all 0xff -> 1024 bytes of "\377". */
	char *src, *exp;
	size_t i;

	src = kunit_kmalloc(test, 256, GFP_KERNEL);
	exp = kunit_kmalloc(test, 256 * 4 + 1, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, src);
	KUNIT_ASSERT_NOT_NULL(test, exp);

	memset(src, 0xff, 256);
	for (i = 0; i < 256; i++)
		memcpy(exp + i * 4, "\\377", 4);
	exp[1024] = '\0';

	KUNIT_EXPECT_EQ(test, string_escape_mem(src, 256, NULL, 0,
						ESCAPE_OCTAL, NULL), 1024);
	KUNIT_EXPECT_EQ(test, string_escape_mem(src, 256, NULL, 0,
						ESCAPE_NP | ESCAPE_HEX, NULL), 256);

	/* Spot-check truncation to an odd boundary deep in the stream. */
	{
		char *buf = kunit_kmalloc(test, 1030, GFP_KERNEL);
		int ret;

		KUNIT_ASSERT_NOT_NULL(test, buf);
		memset(buf, CANARY, 1030);
		ret = string_escape_mem(src, 256, buf, 1021, ESCAPE_OCTAL, NULL);
		KUNIT_EXPECT_EQ(test, ret, 1024);
		KUNIT_EXPECT_EQ(test, memcmp(buf, exp, 1021), 0);
		for (i = 1021; i < 1030; i++)
			KUNIT_EXPECT_EQ(test, (unsigned char)buf[i], CANARY);

		memset(buf, CANARY, 1030);
		ret = string_escape_mem(src, 256, buf, 1030, ESCAPE_OCTAL, NULL);
		KUNIT_EXPECT_EQ(test, ret, 1024);
		KUNIT_EXPECT_EQ(test, memcmp(buf, exp, 1024), 0);
		for (i = 1024; i < 1030; i++)
			KUNIT_EXPECT_EQ(test, (unsigned char)buf[i], CANARY);
	}
}

static void agent_test_wrappers(struct kunit *test)
{
	char buf[16];
	int ret;

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_str("a\tb", buf, sizeof(buf), ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "a\\tb", 4), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[4], CANARY);

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_str_any_np("x\x01", buf, sizeof(buf), NULL);
	KUNIT_EXPECT_EQ(test, ret, 5);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "x\\001", 5), 0);

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem_any_np("\n\x80", 2, buf, sizeof(buf), NULL);
	KUNIT_EXPECT_EQ(test, ret, 6);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "\\n\\200", 6), 0);
}

