// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for string_unescape() from lib/string_helpers.c.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define OUT_SIZE	64
#define POISON		0xA5

/*
 * Run string_unescape() on a mutable copy of @src into a poisoned buffer and
 * check: the return value, the exact bytes written (which may contain '\0'),
 * the terminating NUL, and that nothing beyond the terminator was touched.
 */
static void check_unescape(struct kunit *test, const char *src,
			   unsigned int flags, size_t size,
			   const char *exp, int exp_len)
{
	char in[OUT_SIZE];
	char out[OUT_SIZE];
	int ret;
	int i;

	KUNIT_ASSERT_LT(test, strlen(src), sizeof(in));
	KUNIT_ASSERT_LT(test, (size_t)exp_len, sizeof(out));
	strscpy(in, src, sizeof(in));
	memset(out, POISON, sizeof(out));

	ret = string_unescape(in, out, size, flags);

	KUNIT_EXPECT_EQ_MSG(test, ret, exp_len,
			    "src=\"%s\" flags=%#x size=%zu", src, flags, size);
	KUNIT_EXPECT_EQ_MSG(test, memcmp(out, exp, exp_len), 0,
			    "src=\"%s\" flags=%#x size=%zu: bytes differ",
			    src, flags, size);
	KUNIT_EXPECT_EQ_MSG(test, out[exp_len], '\0',
			    "src=\"%s\": missing NUL at %d", src, exp_len);
	for (i = exp_len + 1; i < OUT_SIZE; i++)
		KUNIT_EXPECT_EQ_MSG(test, (u8)out[i], (u8)POISON,
				    "src=\"%s\": wrote past terminator at %d",
				    src, i);
}

#define CHECK(test, src, flags, size, exp) \
	check_unescape(test, src, flags, size, exp, sizeof(exp) - 1)

/* ---------- Plain input, no escapes ---------- */

static void agent_test_plain_copy(struct kunit *test)
{
	CHECK(test, "", UNESCAPE_ANY, 0, "");
	CHECK(test, "", 0, 0, "");
	CHECK(test, "a", UNESCAPE_ANY, 0, "a");
	CHECK(test, "hello world", UNESCAPE_ANY, 0, "hello world");
	CHECK(test, "hello world", 0, 0, "hello world");
	/* Characters that are only special after a backslash stay as is. */
	CHECK(test, "ntvrf xae\"0123", UNESCAPE_ANY, 0, "ntvrf xae\"0123");
	/* Non-ASCII / high bytes are copied through. */
	CHECK(test, "\x80\xff\x01", UNESCAPE_ANY, 0, "\x80\xff\x01");
}

/* ---------- UNESCAPE_SPACE ---------- */

static void agent_test_space(struct kunit *test)
{
	CHECK(test, "\\n", UNESCAPE_SPACE, 0, "\n");
	CHECK(test, "\\r", UNESCAPE_SPACE, 0, "\r");
	CHECK(test, "\\t", UNESCAPE_SPACE, 0, "\t");
	CHECK(test, "\\v", UNESCAPE_SPACE, 0, "\v");
	CHECK(test, "\\f", UNESCAPE_SPACE, 0, "\f");
	CHECK(test, "a\\nb\\tc\\rd\\ve\\ff", UNESCAPE_SPACE, 0,
	      "a\nb\tc\rd\ve\ff");
	/* Consecutive escapes. */
	CHECK(test, "\\n\\n\\t", UNESCAPE_SPACE, 0, "\n\n\t");
	/* Only the one character after the backslash is consumed. */
	CHECK(test, "\\nn", UNESCAPE_SPACE, 0, "\nn");
	/* Not members of this class: left untouched. */
	CHECK(test, "\\a\\e\\\\\\\"\\x41\\101", UNESCAPE_SPACE, 0,
	      "\\a\\e\\\\\\\"\\x41\\101");
	/* Uppercase is not a space escape. */
	CHECK(test, "\\N\\T", UNESCAPE_SPACE, 0, "\\N\\T");
	/* Space escapes with the flag off are literal. */
	CHECK(test, "\\n\\t", UNESCAPE_OCTAL | UNESCAPE_HEX | UNESCAPE_SPECIAL,
	      0, "\\n\\t");
}

/* ---------- UNESCAPE_OCTAL ---------- */

static void agent_test_octal_basic(struct kunit *test)
{
	CHECK(test, "\\101", UNESCAPE_OCTAL, 0, "A");
	CHECK(test, "\\101\\102\\103", UNESCAPE_OCTAL, 0, "ABC");
	/* One digit. */
	CHECK(test, "\\7", UNESCAPE_OCTAL, 0, "\a");
	CHECK(test, "\\7x", UNESCAPE_OCTAL, 0, "\ax");
	/* Two digits. */
	CHECK(test, "\\12", UNESCAPE_OCTAL, 0, "\n");
	CHECK(test, "\\12x", UNESCAPE_OCTAL, 0, "\nx");
	/* Two digits followed by a non-octal digit. */
	CHECK(test, "\\128", UNESCAPE_OCTAL, 0, "\n8");
	CHECK(test, "\\129", UNESCAPE_OCTAL, 0, "\n9");
	/* Three digits followed by another octal digit: only three used. */
	CHECK(test, "\\1011", UNESCAPE_OCTAL, 0, "A1");
	CHECK(test, "\\0123", UNESCAPE_OCTAL, 0, "\n3");
	/* Leading zeros count as digits. */
	CHECK(test, "\\001", UNESCAPE_OCTAL, 0, "\001");
	CHECK(test, "\\0011", UNESCAPE_OCTAL, 0, "\001" "1");
	/* 8 and 9 are not octal digits. */
	CHECK(test, "\\8", UNESCAPE_OCTAL, 0, "\\8");
	CHECK(test, "\\9", UNESCAPE_OCTAL, 0, "\\9");
	/* Octal escapes with the flag off are literal. */
	CHECK(test, "\\101", UNESCAPE_SPACE | UNESCAPE_HEX | UNESCAPE_SPECIAL,
	      0, "\\101");
}

static void agent_test_octal_nul(struct kunit *test)
{
	/* An embedded NUL byte must be produced and counted. */
	check_unescape(test, "\\0", UNESCAPE_OCTAL, 0, "\0", 1);
	check_unescape(test, "a\\0b", UNESCAPE_OCTAL, 0, "a\0b", 3);
	check_unescape(test, "\\000x", UNESCAPE_OCTAL, 0, "\0x", 2);
	check_unescape(test, "\\00\\0", UNESCAPE_OCTAL, 0, "\0\0", 2);
}

static void agent_test_octal_limits(struct kunit *test)
{
	/* Highest 3-digit value that fits in a byte. */
	CHECK(test, "\\377", UNESCAPE_OCTAL, 0, "\377");
	CHECK(test, "\\3777", UNESCAPE_OCTAL, 0, "\377" "7");
	CHECK(test, "\\376", UNESCAPE_OCTAL, 0, "\376");
	/* \37 then a third digit: 037 = 31 < 32, so the third digit is used. */
	CHECK(test, "\\370", UNESCAPE_OCTAL, 0, "\370");
	/*
	 * First two digits already >= 32 (040 = 32): the third digit must
	 * not be consumed, otherwise the value would overflow a byte.
	 */
	CHECK(test, "\\400", UNESCAPE_OCTAL, 0, " 00");
	CHECK(test, "\\401", UNESCAPE_OCTAL, 0, " 01");
	CHECK(test, "\\777", UNESCAPE_OCTAL, 0, "?77");
	CHECK(test, "\\477", UNESCAPE_OCTAL, 0, "'77");
	/* 2-digit value 037 (31) is the largest that still takes a third. */
	CHECK(test, "\\377", UNESCAPE_OCTAL, 0, "\377");
	CHECK(test, "\\40", UNESCAPE_OCTAL, 0, " ");
	CHECK(test, "\\40x", UNESCAPE_OCTAL, 0, " x");
	/* Max single-digit followed by non-octal. */
	CHECK(test, "\\7a", UNESCAPE_OCTAL, 0, "\aa");
}

/* ---------- UNESCAPE_HEX ---------- */

static void agent_test_hex_basic(struct kunit *test)
{
	CHECK(test, "\\x41", UNESCAPE_HEX, 0, "A");
	CHECK(test, "\\x41\\x42\\x43", UNESCAPE_HEX, 0, "ABC");
	/* One digit. */
	CHECK(test, "\\x4", UNESCAPE_HEX, 0, "\x04");
	CHECK(test, "\\x4g", UNESCAPE_HEX, 0, "\x04" "g");
	CHECK(test, "\\xF", UNESCAPE_HEX, 0, "\x0f");
	/* Two digits exactly; third hex digit is literal. */
	CHECK(test, "\\x414", UNESCAPE_HEX, 0, "A4");
	CHECK(test, "\\x41a", UNESCAPE_HEX, 0, "Aa");
	/* Case-insensitive digits. */
	CHECK(test, "\\x4a", UNESCAPE_HEX, 0, "J");
	CHECK(test, "\\x4A", UNESCAPE_HEX, 0, "J");
	CHECK(test, "\\xaB", UNESCAPE_HEX, 0, "\xab");
	/* Extremes. */
	CHECK(test, "\\xff", UNESCAPE_HEX, 0, "\xff");
	CHECK(test, "\\xFF", UNESCAPE_HEX, 0, "\xff");
	check_unescape(test, "\\x00", UNESCAPE_HEX, 0, "\0", 1);
	check_unescape(test, "\\x0", UNESCAPE_HEX, 0, "\0", 1);
	check_unescape(test, "a\\x00b", UNESCAPE_HEX, 0, "a\0b", 3);
	/* Leading zero. */
	CHECK(test, "\\x0a", UNESCAPE_HEX, 0, "\n");
	/* Hex escapes with the flag off are literal. */
	CHECK(test, "\\x41", UNESCAPE_SPACE | UNESCAPE_OCTAL | UNESCAPE_SPECIAL,
	      0, "\\x41");
}

static void agent_test_hex_invalid(struct kunit *test)
{
	/* "\x" with no digit at all, at end of string and in the middle. */
	CHECK(test, "\\x", UNESCAPE_HEX, 0, "\\x");
	CHECK(test, "\\xg", UNESCAPE_HEX, 0, "\\xg");
	CHECK(test, "\\xzz", UNESCAPE_HEX, 0, "\\xzz");
	CHECK(test, "a\\xb", UNESCAPE_HEX, 0, "a\x0b");
	CHECK(test, "\\x\\x41", UNESCAPE_HEX, 0, "\\xA");
	/* Uppercase X is not a hex introducer. */
	CHECK(test, "\\X41", UNESCAPE_HEX, 0, "\\X41");
	/* A failed hex parse must not advance src past the 'x'. */
	CHECK(test, "\\xq\\x41", UNESCAPE_HEX, 0, "\\xqA");
	/* With ANY, "\x" followed by nothing valid falls through to literal. */
	CHECK(test, "\\x", UNESCAPE_ANY, 0, "\\x");
	CHECK(test, "\\xg", UNESCAPE_ANY, 0, "\\xg");
}

/* ---------- UNESCAPE_SPECIAL ---------- */

static void agent_test_special(struct kunit *test)
{
	CHECK(test, "\\\"", UNESCAPE_SPECIAL, 0, "\"");
	CHECK(test, "\\\\", UNESCAPE_SPECIAL, 0, "\\");
	CHECK(test, "\\a", UNESCAPE_SPECIAL, 0, "\a");
	CHECK(test, "\\e", UNESCAPE_SPECIAL, 0, "\e");
	CHECK(test, "\\e", UNESCAPE_SPECIAL, 0, "\x1b");
	CHECK(test, "x\\\"y\\\\z\\aw\\ev", UNESCAPE_SPECIAL, 0,
	      "x\"y\\z\aw\ev");
	/* "\\n": the double backslash becomes one, the n stays literal. */
	CHECK(test, "\\\\n", UNESCAPE_SPECIAL, 0, "\\n");
	CHECK(test, "\\\\n", UNESCAPE_ANY, 0, "\\n");
	/* "\\\\": two escaped backslashes. */
	CHECK(test, "\\\\\\\\", UNESCAPE_SPECIAL, 0, "\\\\");
	/* Three backslashes: one escaped pair, then a trailing literal. */
	CHECK(test, "\\\\\\", UNESCAPE_SPECIAL, 0, "\\\\");
	/* Not members of this class. */
	CHECK(test, "\\n\\x41\\101", UNESCAPE_SPECIAL, 0, "\\n\\x41\\101");
	/* Single quote is not special. */
	CHECK(test, "\\'", UNESCAPE_SPECIAL, 0, "\\'");
	/* Special escapes with the flag off are literal. */
	CHECK(test, "\\\\\\a\\e\\\"",
	      UNESCAPE_SPACE | UNESCAPE_OCTAL | UNESCAPE_HEX, 0,
	      "\\\\\\a\\e\\\"");
}

/* ---------- Flag combinations and precedence ---------- */

static void agent_test_flags_none(struct kunit *test)
{
	/* With no flags set, everything is copied verbatim. */
	CHECK(test, "\\n\\101\\x41\\\\\\a\\e\\\"\\t", 0, 0,
	      "\\n\\101\\x41\\\\\\a\\e\\\"\\t");
	CHECK(test, "\\", 0, 0, "\\");
	CHECK(test, "\\\\", 0, 0, "\\\\");
	/* Bits outside UNESCAPE_ALL_MASK are ignored. */
	CHECK(test, "\\n\\101", ~UNESCAPE_ALL_MASK, 0, "\\n\\101");
}

static void agent_test_flags_any(struct kunit *test)
{
	CHECK(test, "\\n\\101\\x41\\\\", UNESCAPE_ANY, 0, "\nA" "A\\");
	CHECK(test, "\\t\\r\\v\\f\\a\\e\\\"", UNESCAPE_ANY, 0,
	      "\t\r\v\f\a\e\"");
	CHECK(test, "\\x7e\\176\\\\", UNESCAPE_ANY, 0, "~~\\");
	/* Unknown escape under ANY is preserved verbatim. */
	CHECK(test, "\\q", UNESCAPE_ANY, 0, "\\q");
	CHECK(test, "\\z\\Q\\ ", UNESCAPE_ANY, 0, "\\z\\Q\\ ");
	CHECK(test, "\\8\\9", UNESCAPE_ANY, 0, "\\8\\9");
	CHECK(test, "a\\qb", UNESCAPE_ANY, 0, "a\\qb");
	/* Mixed literal and escaped content. */
	CHECK(test, "key=\\\"val\\x20ue\\\"\\n", UNESCAPE_ANY, 0,
	      "key=\"val ue\"\n");
}

static void agent_test_flags_combinations(struct kunit *test)
{
	unsigned int f;

	/* Each pair of flags handles exactly its own classes. */
	f = UNESCAPE_SPACE | UNESCAPE_OCTAL;
	CHECK(test, "\\n\\101\\x41\\\\", f, 0, "\nA\\x41\\\\");
	f = UNESCAPE_SPACE | UNESCAPE_HEX;
	CHECK(test, "\\n\\101\\x41\\\\", f, 0, "\n\\101A\\\\");
	f = UNESCAPE_SPACE | UNESCAPE_SPECIAL;
	CHECK(test, "\\n\\101\\x41\\\\", f, 0, "\n\\101\\x41\\");
	f = UNESCAPE_OCTAL | UNESCAPE_HEX;
	CHECK(test, "\\n\\101\\x41\\\\", f, 0, "\\nAA\\\\");
	f = UNESCAPE_OCTAL | UNESCAPE_SPECIAL;
	CHECK(test, "\\n\\101\\x41\\\\", f, 0, "\\nA\\x41\\");
	f = UNESCAPE_HEX | UNESCAPE_SPECIAL;
	CHECK(test, "\\n\\101\\x41\\\\", f, 0, "\\n\\101A\\");

	/*
	 * A backslash that is not decoded is emitted literally and the
	 * following character is then processed as plain text, so an
	 * un-decoded escape never swallows a later escape.
	 */
	CHECK(test, "\\x41\\n", UNESCAPE_SPACE, 0, "\\x41\n");
	CHECK(test, "\\n\\x41", UNESCAPE_HEX, 0, "\\nA");
}

/* ---------- Trailing backslash / error paths ---------- */

static void agent_test_trailing_backslash(struct kunit *test)
{
	CHECK(test, "\\", UNESCAPE_ANY, 0, "\\");
	CHECK(test, "abc\\", UNESCAPE_ANY, 0, "abc\\");
	CHECK(test, "\\n\\", UNESCAPE_ANY, 0, "\n\\");
	CHECK(test, "\\\\\\", UNESCAPE_ANY, 0, "\\\\");
	/* Trailing backslash with a size limit still has room for it. */
	CHECK(test, "a\\", UNESCAPE_ANY, 3, "a\\");
	CHECK(test, "a\\", UNESCAPE_ANY, 2, "a");
}

/* ---------- Size handling ---------- */

static void agent_test_size_zero_unlimited(struct kunit *test)
{
	char in[OUT_SIZE];
	char out[OUT_SIZE];
	int i, ret;

	/* size == 0 means no limit. Fill 60 characters. */
	for (i = 0; i < 60; i++)
		in[i] = 'a' + (i % 26);
	in[60] = '\0';
	memset(out, POISON, sizeof(out));
	ret = string_unescape(in, out, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 60);
	KUNIT_EXPECT_STREQ(test, out, in);
	KUNIT_EXPECT_EQ(test, out[60], '\0');
	KUNIT_EXPECT_EQ(test, (u8)out[61], (u8)POISON);
}

static void agent_test_size_plain_truncation(struct kunit *test)
{
	/* size 1: only room for the terminator. */
	CHECK(test, "abcdef", UNESCAPE_ANY, 1, "");
	CHECK(test, "", UNESCAPE_ANY, 1, "");
	/* size 2: one character. */
	CHECK(test, "abcdef", UNESCAPE_ANY, 2, "a");
	/* size N: N-1 characters. */
	CHECK(test, "abcdef", UNESCAPE_ANY, 3, "ab");
	CHECK(test, "abcdef", UNESCAPE_ANY, 6, "abcde");
	/* size exactly strlen+1: whole string fits. */
	CHECK(test, "abcdef", UNESCAPE_ANY, 7, "abcdef");
	/* size larger than needed. */
	CHECK(test, "abcdef", UNESCAPE_ANY, 8, "abcdef");
	CHECK(test, "abcdef", UNESCAPE_ANY, 63, "abcdef");
	/* Input shorter than the limit with no flags. */
	CHECK(test, "ab", 0, 10, "ab");
}

static void agent_test_size_escape_at_limit(struct kunit *test)
{
	/*
	 * An escape sequence is only decoded if there is room for two
	 * characters (the backslash and the one after it). When the buffer
	 * has only one free slot, the backslash is copied literally.
	 */
	CHECK(test, "\\n", UNESCAPE_SPACE, 1, "");
	CHECK(test, "\\n", UNESCAPE_SPACE, 2, "\\");
	CHECK(test, "\\n", UNESCAPE_SPACE, 3, "\n");
	CHECK(test, "\\n", UNESCAPE_SPACE, 4, "\n");

	/* Same shape, with a prefix pushing the escape to the boundary. */
	CHECK(test, "ab\\n", UNESCAPE_SPACE, 3, "ab");
	CHECK(test, "ab\\n", UNESCAPE_SPACE, 4, "ab\\");
	CHECK(test, "ab\\n", UNESCAPE_SPACE, 5, "ab\n");
	CHECK(test, "ab\\n", UNESCAPE_SPACE, 6, "ab\n");

	/* Decoded escape accounts for two slots: nothing follows it at 3. */
	CHECK(test, "\\nX", UNESCAPE_SPACE, 3, "\n");
	CHECK(test, "\\nX", UNESCAPE_SPACE, 4, "\nX");
	CHECK(test, "\\nXY", UNESCAPE_SPACE, 4, "\nX");
	CHECK(test, "\\nXY", UNESCAPE_SPACE, 5, "\nXY");

	/* Multi-character escapes cost the same two slots as a short one. */
	CHECK(test, "\\101", UNESCAPE_OCTAL, 2, "\\");
	CHECK(test, "\\101", UNESCAPE_OCTAL, 3, "A");
	CHECK(test, "\\101Z", UNESCAPE_OCTAL, 3, "A");
	CHECK(test, "\\101Z", UNESCAPE_OCTAL, 4, "AZ");
	CHECK(test, "\\x41", UNESCAPE_HEX, 2, "\\");
	CHECK(test, "\\x41", UNESCAPE_HEX, 3, "A");
	CHECK(test, "\\x41Z", UNESCAPE_HEX, 3, "A");
	CHECK(test, "\\x41Z", UNESCAPE_HEX, 4, "AZ");
	CHECK(test, "\\\\", UNESCAPE_SPECIAL, 2, "\\");
	CHECK(test, "\\\\", UNESCAPE_SPECIAL, 3, "\\");
	CHECK(test, "\\\\Z", UNESCAPE_SPECIAL, 3, "\\");
	CHECK(test, "\\\\Z", UNESCAPE_SPECIAL, 4, "\\Z");

	/* Back-to-back escapes under a limit. */
	CHECK(test, "\\n\\t\\r", UNESCAPE_SPACE, 3, "\n");
	CHECK(test, "\\n\\t\\r", UNESCAPE_SPACE, 4, "\n\\");
	CHECK(test, "\\n\\t\\r", UNESCAPE_SPACE, 5, "\n\t");
	CHECK(test, "\\n\\t\\r", UNESCAPE_SPACE, 7, "\n\t\r");

	/* An unknown escape near the limit still only copies what fits. */
	CHECK(test, "\\q", UNESCAPE_ANY, 2, "\\");
	CHECK(test, "\\q", UNESCAPE_ANY, 3, "\\q");
	CHECK(test, "\\qZ", UNESCAPE_ANY, 3, "\\q");
	CHECK(test, "\\qZ", UNESCAPE_ANY, 4, "\\qZ");
}

/* ---------- In-place operation ---------- */

static void agent_test_inplace(struct kunit *test)
{
	char buf[OUT_SIZE];
	int ret;

	strscpy(buf, "a\\tb\\x41\\101\\\\c", sizeof(buf));
	ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "a\tbAA\\c");

	strscpy(buf, "\\n\\n\\n", sizeof(buf));
	ret = string_unescape(buf, buf, 0, UNESCAPE_SPACE);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_STREQ(test, buf, "\n\n\n");

	/* In place with a size limit. */
	strscpy(buf, "abc\\ndef", sizeof(buf));
	ret = string_unescape(buf, buf, 6, UNESCAPE_SPACE);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, buf, "abc\n");

	/* Nothing to do in place. */
	strscpy(buf, "plain", sizeof(buf));
	ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 5);
	KUNIT_EXPECT_STREQ(test, buf, "plain");

	/* Empty string in place. */
	buf[0] = '\0';
	buf[1] = 'Z';
	ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, buf[0], '\0');
	KUNIT_EXPECT_EQ(test, buf[1], 'Z');
}

/* ---------- Inline wrappers from the header ---------- */

static void agent_test_wrappers(struct kunit *test)
{
	char buf[OUT_SIZE];
	char out[OUT_SIZE];
	int ret;

	strscpy(buf, "\\x41\\n\\101\\\\", sizeof(buf));
	memset(out, POISON, sizeof(out));
	ret = string_unescape_any(buf, out, sizeof(out));
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, out, "A\nA\\");

	strscpy(buf, "\\x41\\n\\101\\\\", sizeof(buf));
	ret = string_unescape_any_inplace(buf);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, buf, "A\nA\\");

	strscpy(buf, "\\x41\\n\\101\\\\", sizeof(buf));
	ret = string_unescape_inplace(buf, UNESCAPE_HEX);
	KUNIT_EXPECT_EQ(test, ret, 9);
	KUNIT_EXPECT_STREQ(test, buf, "A\\n\\101\\\\");
}

/* ---------- Return value equals strlen(dst) when no NULs produced -------- */

static void agent_test_return_value(struct kunit *test)
{
	static const char * const inputs[] = {
		"", "x", "\\n", "\\\\", "\\x41\\x42", "\\101\\102\\103",
		"tail\\", "\\q\\z", "mix\\ted \\x20 \\040\\\"",
	};
	char in[OUT_SIZE];
	char out[OUT_SIZE];
	int i, ret;

	for (i = 0; i < ARRAY_SIZE(inputs); i++) {
		strscpy(in, inputs[i], sizeof(in));
		ret = string_unescape(in, out, sizeof(out), UNESCAPE_ANY);
		KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(out),
				    "input \"%s\"", inputs[i]);
		KUNIT_EXPECT_LE_MSG(test, ret, (int)strlen(inputs[i]),
				    "input \"%s\": output longer than input",
				    inputs[i]);
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_plain_copy),
	KUNIT_CASE(agent_test_space),
	KUNIT_CASE(agent_test_octal_basic),
	KUNIT_CASE(agent_test_octal_nul),
	KUNIT_CASE(agent_test_octal_limits),
	KUNIT_CASE(agent_test_hex_basic),
	KUNIT_CASE(agent_test_hex_invalid),
	KUNIT_CASE(agent_test_special),
	KUNIT_CASE(agent_test_flags_none),
	KUNIT_CASE(agent_test_flags_any),
	KUNIT_CASE(agent_test_flags_combinations),
	KUNIT_CASE(agent_test_trailing_backslash),
	KUNIT_CASE(agent_test_size_zero_unlimited),
	KUNIT_CASE(agent_test_size_plain_truncation),
	KUNIT_CASE(agent_test_size_escape_at_limit),
	KUNIT_CASE(agent_test_inplace),
	KUNIT_CASE(agent_test_wrappers),
	KUNIT_CASE(agent_test_return_value),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for string_unescape()");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for get_option() from lib/cmdline.c.
 *
 * Contract under test:
 *   0 - no int in string (a leading '-' is still consumed)
 *   1 - int found, no subsequent comma
 *   2 - int found including a subsequent comma (comma consumed)
 *   3 - int found followed by a hyphen (hyphen NOT consumed)
 *   @pint may be NULL (validator mode).
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>
#include <linux/string.h>

#define SENTINEL	0x5a5a5a5a

/*
 * Run get_option() on a writable copy of @input and check return value,
 * parsed value and how many characters were consumed.
 */
static void check_option(struct kunit *test, const char *input,
			 int exp_ret, int exp_val, size_t exp_consumed)
{
	char buf[64];
	char *str = buf;
	int val = SENTINEL;
	int ret;

	KUNIT_ASSERT_LT(test, strlen(input), sizeof(buf));
	strcpy(buf, input);

	ret = get_option(&str, &val);

	KUNIT_EXPECT_EQ_MSG(test, ret, exp_ret, "input \"%s\"", input);
	KUNIT_EXPECT_EQ_MSG(test, val, exp_val, "input \"%s\"", input);
	KUNIT_EXPECT_PTR_EQ_MSG(test, str, buf + exp_consumed,
				"input \"%s\": consumed %td, expected %zu",
				input, str - buf, exp_consumed);
}

/* ---- Error paths / "no int" cases ---------------------------------- */

static void get_option_null_string(struct kunit *test)
{
	char *str = NULL;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	/* Nothing parsed: value must be left alone, pointer still NULL. */
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
	KUNIT_EXPECT_NULL(test, str);
}

static void get_option_empty_string(struct kunit *test)
{
	char buf[] = "";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
	KUNIT_EXPECT_PTR_EQ(test, str, buf);
}

static void get_option_no_digits(struct kunit *test)
{
	/* No digits: return 0, pointer unchanged, value reported as 0. */
	check_option(test, "abc", 0, 0, 0);
	check_option(test, "x5", 0, 0, 0);
	check_option(test, ",", 0, 0, 0);
	check_option(test, ",5", 0, 0, 0);
	check_option(test, " 5", 0, 0, 0);	/* no whitespace skipping */
	check_option(test, "+5", 0, 0, 0);	/* '+' is not accepted */
	check_option(test, "\t5", 0, 0, 0);
}

static void get_option_lone_hyphen(struct kunit *test)
{
	/* A leading hyphen without an integer is consumed but yields 0. */
	check_option(test, "-", 0, 0, 1);
	check_option(test, "-abc", 0, 0, 1);
	check_option(test, "-,", 0, 0, 1);
	check_option(test, "--5", 0, 0, 1);	/* only the first '-' goes */
	check_option(test, "- 5", 0, 0, 1);
}

/* ---- Plain integers (return 1) ------------------------------------- */

static void get_option_single_int(struct kunit *test)
{
	check_option(test, "0", 1, 0, 1);
	check_option(test, "1", 1, 1, 1);
	check_option(test, "7", 1, 7, 1);
	check_option(test, "9", 1, 9, 1);
	check_option(test, "10", 1, 10, 2);
	check_option(test, "42", 1, 42, 2);
	check_option(test, "123", 1, 123, 3);
	check_option(test, "1000000", 1, 1000000, 7);
	check_option(test, "00", 1, 0, 2);
	check_option(test, "007", 1, 7, 3);
}

static void get_option_negative_int(struct kunit *test)
{
	check_option(test, "-0", 1, 0, 2);
	check_option(test, "-1", 1, -1, 2);
	check_option(test, "-5", 1, -5, 2);
	check_option(test, "-42", 1, -42, 3);
	check_option(test, "-123", 1, -123, 4);
}

static void get_option_int_limits(struct kunit *test)
{
	check_option(test, "2147483647", 1, INT_MAX, 10);
	check_option(test, "-2147483647", 1, -INT_MAX, 11);
	check_option(test, "-2147483648", 1, INT_MIN, 11);
	check_option(test, "0x7fffffff", 1, INT_MAX, 10);
	check_option(test, "-0x80000000", 1, INT_MIN, 11);
}

static void get_option_radix(struct kunit *test)
{
	/* Base 0: hex prefix, leading-zero octal, otherwise decimal. */
	check_option(test, "0x10", 1, 16, 4);
	check_option(test, "0X10", 1, 16, 4);
	check_option(test, "0xff", 1, 255, 4);
	check_option(test, "0xFF", 1, 255, 4);
	check_option(test, "0xa", 1, 10, 3);
	check_option(test, "-0x10", 1, -16, 5);
	check_option(test, "010", 1, 8, 3);
	check_option(test, "017", 1, 15, 3);
	check_option(test, "-010", 1, -8, 4);
	/* "0x" with no hex digit after it is octal 0 followed by junk. */
	check_option(test, "0x", 1, 0, 1);
	check_option(test, "0xg", 1, 0, 1);
	/* Octal stops at the first non-octal digit. */
	check_option(test, "08", 1, 0, 1);
	check_option(test, "0789", 1, 7, 2);
}

static void get_option_trailing_junk(struct kunit *test)
{
	/* Stop at the first non-digit that is neither ',' nor '-'. */
	check_option(test, "5x", 1, 5, 1);
	check_option(test, "5 6", 1, 5, 1);
	check_option(test, "5;6", 1, 5, 1);
	check_option(test, "5:6", 1, 5, 1);
	check_option(test, "5.6", 1, 5, 1);
	check_option(test, "12abc", 1, 12, 2);
	check_option(test, "1f", 1, 1, 1);	/* no hex without prefix */
	check_option(test, "-7x", 1, -7, 2);
	check_option(test, "5+6", 1, 5, 1);
	check_option(test, "5\n", 1, 5, 1);
}

/* ---- Comma handling (return 2) ------------------------------------- */

static void get_option_comma(struct kunit *test)
{
	/* The comma is consumed; the pointer lands right after it. */
	check_option(test, "5,", 2, 5, 2);
	check_option(test, "0,", 2, 0, 2);
	check_option(test, "5,6", 2, 5, 2);
	check_option(test, "42,7", 2, 42, 3);
	check_option(test, "123,456", 2, 123, 4);
	check_option(test, "-5,", 2, -5, 3);
	check_option(test, "-5,6", 2, -5, 3);
	check_option(test, "0x10,", 2, 16, 5);
	check_option(test, "010,", 2, 8, 4);
	/* Only one comma is consumed. */
	check_option(test, "5,,6", 2, 5, 2);
	/* Comma followed by other junk is still return 2. */
	check_option(test, "5,x", 2, 5, 2);
	check_option(test, "5,-", 2, 5, 2);
}

/* ---- Range hyphen handling (return 3) ------------------------------ */

static void get_option_range_hyphen(struct kunit *test)
{
	/* The hyphen is NOT consumed; the pointer stays on it. */
	check_option(test, "1-3", 3, 1, 1);
	check_option(test, "0-9", 3, 0, 1);
	check_option(test, "10-20", 3, 10, 2);
	check_option(test, "123-456", 3, 123, 3);
	check_option(test, "5-", 3, 5, 1);
	check_option(test, "5-,", 3, 5, 1);
	check_option(test, "5-x", 3, 5, 1);
	check_option(test, "-5-3", 3, -5, 2);
	check_option(test, "0x10-0x20", 3, 16, 4);
	check_option(test, "5--3", 3, 5, 1);
}

/* ---- pint == NULL (validator mode) --------------------------------- */

static void get_option_null_pint(struct kunit *test)
{
	char buf1[] = "123,45";
	char buf2[] = "7-9";
	char buf3[] = "abc";
	char buf4[] = "-";
	char buf5[] = "";
	char *str;

	str = buf1;
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 2);
	KUNIT_EXPECT_PTR_EQ(test, str, buf1 + 4);

	str = buf2;
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 3);
	KUNIT_EXPECT_PTR_EQ(test, str, buf2 + 1);

	str = buf3;
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
	KUNIT_EXPECT_PTR_EQ(test, str, buf3);

	str = buf4;
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
	KUNIT_EXPECT_PTR_EQ(test, str, buf4 + 1);

	str = buf5;
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
	KUNIT_EXPECT_PTR_EQ(test, str, buf5);

	str = NULL;
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
	KUNIT_EXPECT_NULL(test, str);
}

/* ---- Sequential parsing of a full option list ---------------------- */

static void get_option_sequence_commas(struct kunit *test)
{
	char buf[] = "1,22,-3,0x10,5";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 2);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 22);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 5);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, -3);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 8);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 16);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 13);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 1);
	KUNIT_EXPECT_EQ(test, val, 5);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 14);
	KUNIT_EXPECT_EQ(test, *str, '\0');

	/* At end of string: nothing more, value untouched. */
	val = SENTINEL;
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 14);
}

static void get_option_sequence_range(struct kunit *test)
{
	/* Mimic how get_options() walks "1-3,7": 3 then consume '-' etc. */
	char buf[] = "1-3,7";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 3);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 1);
	KUNIT_EXPECT_EQ(test, *str, '-');

	/*
	 * Calling again on "-3,7" treats the hyphen as a sign: value -3,
	 * comma consumed.
	 */
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, -3);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 4);

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 1);
	KUNIT_EXPECT_EQ(test, val, 7);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 5);
}

static void get_option_sequence_trailing_comma(struct kunit *test)
{
	char buf[] = "9,";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 9);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 2);

	/* Now at the terminating NUL: no int, nothing consumed. */
	val = SENTINEL;
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 2);
}

static void get_option_sequence_stops_on_junk(struct kunit *test)
{
	char buf[] = "4,x,5";
	char *str = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 4);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 2);

	/* "x,5": not an int; pointer must not advance. */
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_EQ(test, val, 0);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 2);

	/* And it stays stuck there on a repeated call. */
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
	KUNIT_EXPECT_PTR_EQ(test, str, buf + 2);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(get_option_null_string),
	KUNIT_CASE(get_option_empty_string),
	KUNIT_CASE(get_option_no_digits),
	KUNIT_CASE(get_option_lone_hyphen),
	KUNIT_CASE(get_option_single_int),
