	KUNIT_CASE(get_option_int_limits),
	KUNIT_CASE(get_option_radix),
	KUNIT_CASE(get_option_trailing_junk),
	KUNIT_CASE(get_option_comma),
	KUNIT_CASE(get_option_range_hyphen),
	KUNIT_CASE(get_option_null_pint),
	KUNIT_CASE(get_option_sequence_commas),
	KUNIT_CASE(get_option_sequence_range),
	KUNIT_CASE(get_option_sequence_trailing_comma),
	KUNIT_CASE(get_option_sequence_stops_on_junk),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
