/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for get_options() from lib/cmdline.c.
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/limits.h>
#include <linux/string.h>

/* Size of the scratch array handed to get_options() in every test. */
#define AGENT_NINTS	16
/* Value no test input ever produces, used to detect untouched slots. */
#define AGENT_SENTINEL	0x5a5a5a5a

/*
 * Fill @ints with the sentinel, run get_options() and verify that the
 * returned pointer is @in + @exp_off, i.e. that parsing stopped at the
 * expected character.
 */
static void agent_run(struct kunit *test, const char *in, int nints,
		      int *ints, int exp_off)
{
	char *end;
	int i;

	for (i = 0; i < AGENT_NINTS; i++)
		ints[i] = AGENT_SENTINEL;

	end = get_options(in, nints, ints);

	KUNIT_EXPECT_PTR_EQ_MSG(test, end, (char *)in + exp_off,
				"\"%s\" nints=%d: stopped at offset %td, expected %d",
				in, nints, end - in, exp_off);
}

/* Every slot from @from up to the end of the scratch array is untouched. */
static void agent_expect_untouched(struct kunit *test, const char *in,
				   const int *ints, int from)
{
	int i;

	for (i = from; i < AGENT_NINTS; i++)
		KUNIT_EXPECT_EQ_MSG(test, ints[i], AGENT_SENTINEL,
				    "\"%s\": slot %d was written (%d)",
				    in, i, ints[i]);
}

/*
 * Compare ints[0] against @count and ints[1..count] against @exp, then
 * make sure nothing beyond ints[count] has been written.
 */
static void agent_expect_values(struct kunit *test, const char *in,
				const int *ints, const int *exp, int count)
{
	int i;

	KUNIT_EXPECT_EQ_MSG(test, ints[0], count,
			    "\"%s\": parsed %d numbers, expected %d",
			    in, ints[0], count);
	for (i = 0; i < count; i++)
		KUNIT_EXPECT_EQ_MSG(test, ints[i + 1], exp[i],
				    "\"%s\": slot %d is %d, expected %d",
				    in, i + 1, ints[i + 1], exp[i]);
	agent_expect_untouched(test, in, ints, count + 1);
}

