static void agent_test_empty(struct kunit *test)
{
	int ints[AGENT_NINTS];

	agent_run(test, "", AGENT_NINTS, ints, 0);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	agent_expect_untouched(test, "", ints, 1);

	/* NULL string: get_option() bails out immediately. */
	agent_run(test, NULL, AGENT_NINTS, ints, 0);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	agent_expect_untouched(test, "(null)", ints, 1);
}

