static void agent_test_range_truncated(struct kunit *test)
{
	int ints[AGENT_NINTS];

	/*
	 * "1-5" needs five slots; with nints=3 get_range() must stop after
	 * writing exactly two values (no overrun), the string is left at the
	 * upper bound and ints[0] reports the number of range elements the
	 * implementation accounted for (the full range minus its last
	 * element, as the code does today).
	 */
	agent_run(test, "1-5", 3, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 4);
	KUNIT_EXPECT_EQ(test, ints[1], 1);
	KUNIT_EXPECT_EQ(test, ints[2], 2);
	agent_expect_untouched(test, "1-5", ints, 3);

	/* nints=5: four slots, all filled by the range, "5" never parsed. */
	agent_run(test, "1-5", 5, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 4);
	KUNIT_EXPECT_EQ(test, ints[1], 1);
	KUNIT_EXPECT_EQ(test, ints[2], 2);
	KUNIT_EXPECT_EQ(test, ints[3], 3);
	KUNIT_EXPECT_EQ(test, ints[4], 4);
	agent_expect_untouched(test, "1-5", ints, 5);
}

