/* ---- Error paths ------------------------------------------------------ */

static void agent_test_garbage(struct kunit *test)
{
	int ints[AGENT_NINTS];

	agent_run(test, "abc", AGENT_NINTS, ints, 0);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	/* No leading whitespace skipping, no '+' sign. */
	agent_run(test, " 1", AGENT_NINTS, ints, 0);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	agent_run(test, "+2", AGENT_NINTS, ints, 0);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	/* A leading comma yields nothing and is not consumed. */
	agent_run(test, ",1", AGENT_NINTS, ints, 0);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_test_garbage_tail(struct kunit *test)
{
	static const int exp[] = { 1, 2 };
	int ints[AGENT_NINTS];

	/* Non-numeric tail: parse stops at it. */
	agent_run(test, "1,2,abc", AGENT_NINTS, ints, 4);
	agent_expect_values(test, "1,2,abc", ints, exp, ARRAY_SIZE(exp));

	/* Number immediately followed by junk: number kept, stop at junk. */
	agent_run(test, "1,2x", AGENT_NINTS, ints, 3);
	agent_expect_values(test, "1,2x", ints, exp, ARRAY_SIZE(exp));

	/* Space terminates the list. */
	agent_run(test, "1,2 3", AGENT_NINTS, ints, 3);
	agent_expect_values(test, "1,2 3", ints, exp, ARRAY_SIZE(exp));
}

static void agent_test_junk_first(struct kunit *test)
{
