	int ints[AGENT_NINTS];

	agent_run(test, "1x,2", AGENT_NINTS, ints, 1);
	agent_expect_values(test, "1x,2", ints, exp, ARRAY_SIZE(exp));
}

static void agent_test_double_comma(struct kunit *test)
{
	static const int exp[] = { 1 };
	int ints[AGENT_NINTS];

	/* The first comma is consumed, the second one stops the parse. */
	agent_run(test, "1,,2", AGENT_NINTS, ints, 2);
	agent_expect_values(test, "1,,2", ints, exp, ARRAY_SIZE(exp));
}

static void agent_test_lone_hyphen(struct kunit *test)
{
	int ints[AGENT_NINTS];

	/* A hyphen with no digits is consumed but yields no integer. */
	agent_run(test, "-", AGENT_NINTS, ints, 1);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	agent_run(test, "-,5", AGENT_NINTS, ints, 1);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	agent_run(test, "--7", AGENT_NINTS, ints, 1);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_test_reversed_range(struct kunit *test)
{
	int ints[AGENT_NINTS];

	/* Upper bound below lower bound: nothing collected, stop at upper. */
	agent_run(test, "9-7", AGENT_NINTS, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	agent_expect_untouched(test, "9-7", ints, 2);

	agent_run(test, "5-4", AGENT_NINTS, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	agent_expect_untouched(test, "5-4", ints, 2);

	/* Also when preceded by a valid list element. */
	agent_run(test, "1,9-7", AGENT_NINTS, ints, 4);
	KUNIT_EXPECT_EQ(test, ints[0], 1);
	KUNIT_EXPECT_EQ(test, ints[1], 1);
	agent_expect_untouched(test, "1,9-7", ints, 3);
}

static void agent_test_open_range(struct kunit *test)
{
	int ints[AGENT_NINTS];

	/* Missing upper bound reads as 0, which is below the lower bound. */
	agent_run(test, "7-", AGENT_NINTS, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	agent_run(test, "5-a", AGENT_NINTS, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	agent_run(test, "7--9", AGENT_NINTS, ints, 2);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_test_zero_range_tail(struct kunit *test)
{
	static const int exp[] = { 0, 1, -3, 6 };
	int ints[AGENT_NINTS];

	agent_run(test, "0-1,-3,6", AGENT_NINTS, ints, 8);
	agent_expect_values(test, "0-1,-3,6", ints, exp, ARRAY_SIZE(exp));
}

