/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for memparse() from lib/cmdline.c.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

/*
 * Helper: parse @str, check the returned value and the number of characters
 * consumed (i.e. where *retptr ends up relative to the start of @str).
 */
static void check_memparse(struct kunit *test, const char *str,
			   unsigned long long expected, size_t consumed)
{
	char *end = NULL;
	unsigned long long ret;

	ret = memparse(str, &end);
	KUNIT_EXPECT_EQ_MSG(test, ret, expected, "value for \"%s\"", str);
	KUNIT_EXPECT_PTR_EQ_MSG(test, (const char *)end, str + consumed,
				"retptr for \"%s\" (consumed %zu, expected %zu)",
				str, (size_t)(end - str), consumed);
}

/* ---- plain numbers, no suffix ---- */

static void memparse_decimal_test(struct kunit *test)
{
	check_memparse(test, "1", 1, 1);
	check_memparse(test, "9", 9, 1);
	check_memparse(test, "10", 10, 2);
	check_memparse(test, "123", 123, 3);
	check_memparse(test, "4096", 4096, 4);
	check_memparse(test, "1023", 1023, 4);
	check_memparse(test, "1024", 1024, 4);
	check_memparse(test, "1025", 1025, 4);
	check_memparse(test, "18446744073709551615", ULLONG_MAX, 20);
}

static void memparse_zero_test(struct kunit *test)
{
	check_memparse(test, "0", 0, 1);
	check_memparse(test, "00", 0, 2);
	check_memparse(test, "000", 0, 3);
	check_memparse(test, "0K", 0, 2);
	check_memparse(test, "0M", 0, 2);
	check_memparse(test, "0E", 0, 2);
	check_memparse(test, "0x0", 0, 3);
}

static void memparse_hex_test(struct kunit *test)
{
	check_memparse(test, "0x1", 0x1, 3);
	check_memparse(test, "0X1", 0x1, 3);
	check_memparse(test, "0xf", 0xf, 3);
	check_memparse(test, "0xF", 0xF, 3);
	check_memparse(test, "0xa", 0xa, 3);
	check_memparse(test, "0x10", 0x10, 4);
	check_memparse(test, "0xff", 0xff, 4);
	check_memparse(test, "0x100", 0x100, 5);
	check_memparse(test, "0xdeadbeef", 0xdeadbeefULL, 10);
	check_memparse(test, "0xDEADBEEF", 0xdeadbeefULL, 10);
	check_memparse(test, "0xffffffffffffffff", ULLONG_MAX, 18);
	/* hex digit after the prefix that is not valid in octal/decimal */
	check_memparse(test, "0x8", 8, 3);
	check_memparse(test, "0x9", 9, 3);
}

static void memparse_octal_test(struct kunit *test)
{
	check_memparse(test, "01", 1, 2);
	check_memparse(test, "07", 7, 2);
	check_memparse(test, "010", 8, 3);
	check_memparse(test, "017", 15, 3);
	check_memparse(test, "020", 16, 3);
	check_memparse(test, "0777", 0777, 4);
	check_memparse(test, "0100", 64, 4);
	/* '8' and '9' are not octal digits: parsing stops there */
	check_memparse(test, "08", 0, 1);
	check_memparse(test, "09", 0, 1);
	check_memparse(test, "018", 1, 2);
	check_memparse(test, "0789", 7, 2);
}

/* ---- each suffix, lower and upper case ---- */

static void memparse_suffix_k_test(struct kunit *test)
{
	check_memparse(test, "1k", 1ULL << 10, 2);
	check_memparse(test, "1K", 1ULL << 10, 2);
	check_memparse(test, "2k", 2048, 2);
	check_memparse(test, "3K", 3072, 2);
	check_memparse(test, "1023k", 1023ULL << 10, 5);
	check_memparse(test, "1024K", 1ULL << 20, 5);
	check_memparse(test, "0x10k", 16ULL << 10, 5);
	check_memparse(test, "010K", 8ULL << 10, 4);
}

static void memparse_suffix_m_test(struct kunit *test)
{
	check_memparse(test, "1m", 1ULL << 20, 2);
	check_memparse(test, "1M", 1ULL << 20, 2);
	check_memparse(test, "16M", 16ULL << 20, 3);
	check_memparse(test, "1023M", 1023ULL << 20, 5);
	check_memparse(test, "1024m", 1ULL << 30, 5);
	check_memparse(test, "0x10M", 16ULL << 20, 5);
}

static void memparse_suffix_g_test(struct kunit *test)
{
	check_memparse(test, "1g", 1ULL << 30, 2);
	check_memparse(test, "1G", 1ULL << 30, 2);
	check_memparse(test, "4G", 4ULL << 30, 2);
	check_memparse(test, "1024g", 1ULL << 40, 5);
	check_memparse(test, "0x4G", 4ULL << 30, 4);
}

static void memparse_suffix_t_test(struct kunit *test)
{
	check_memparse(test, "1t", 1ULL << 40, 2);
	check_memparse(test, "1T", 1ULL << 40, 2);
	check_memparse(test, "2T", 2ULL << 40, 2);
	check_memparse(test, "1024t", 1ULL << 50, 5);
}

static void memparse_suffix_p_test(struct kunit *test)
{
	check_memparse(test, "1p", 1ULL << 50, 2);
	check_memparse(test, "1P", 1ULL << 50, 2);
	check_memparse(test, "3P", 3ULL << 50, 2);
	check_memparse(test, "1024p", 1ULL << 60, 5);
}

static void memparse_suffix_e_test(struct kunit *test)
{
	check_memparse(test, "1e", 1ULL << 60, 2);
	check_memparse(test, "1E", 1ULL << 60, 2);
	check_memparse(test, "15E", 15ULL << 60, 3);
	/* after a hex number 'E'/'e' is a digit, not a suffix */
	check_memparse(test, "0xfE", 0xfe, 4);
	check_memparse(test, "0x1e", 0x1e, 4);
	/* ...but octal/decimal numbers do take the E suffix */
	check_memparse(test, "017E", 15ULL << 60, 4);
}

/*
 * The suffixes form a strict chain: each step is exactly one factor of 1024
 * more than the previous one.  An off-by-one shift in any case label would
 * break one of these relations.
 */
static void memparse_suffix_chain_test(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, memparse("1K", NULL), memparse("1024", NULL));
	KUNIT_EXPECT_EQ(test, memparse("1M", NULL), memparse("1024K", NULL));
	KUNIT_EXPECT_EQ(test, memparse("1G", NULL), memparse("1024M", NULL));
	KUNIT_EXPECT_EQ(test, memparse("1T", NULL), memparse("1024G", NULL));
	KUNIT_EXPECT_EQ(test, memparse("1P", NULL), memparse("1024T", NULL));
	KUNIT_EXPECT_EQ(test, memparse("1E", NULL), memparse("1024P", NULL));

	KUNIT_EXPECT_EQ(test, memparse("1M", NULL) / memparse("1K", NULL), 1024ULL);
	KUNIT_EXPECT_EQ(test, memparse("1G", NULL) / memparse("1M", NULL), 1024ULL);
	KUNIT_EXPECT_EQ(test, memparse("1T", NULL) / memparse("1G", NULL), 1024ULL);
	KUNIT_EXPECT_EQ(test, memparse("1P", NULL) / memparse("1T", NULL), 1024ULL);
	KUNIT_EXPECT_EQ(test, memparse("1E", NULL) / memparse("1P", NULL), 1024ULL);

	/* lower and upper case must be identical */
	KUNIT_EXPECT_EQ(test, memparse("7k", NULL), memparse("7K", NULL));
	KUNIT_EXPECT_EQ(test, memparse("7m", NULL), memparse("7M", NULL));
	KUNIT_EXPECT_EQ(test, memparse("7g", NULL), memparse("7G", NULL));
	KUNIT_EXPECT_EQ(test, memparse("7t", NULL), memparse("7T", NULL));
	KUNIT_EXPECT_EQ(test, memparse("7p", NULL), memparse("7P", NULL));
	KUNIT_EXPECT_EQ(test, memparse("7e", NULL), memparse("7E", NULL));
}

/* ---- wrap-around at the top of the 64-bit range ---- */

static void memparse_overflow_shift_test(struct kunit *test)
{
	/* 16 << 60 wraps to exactly zero in 64 bits */
	check_memparse(test, "16E", 0, 3);
	check_memparse(test, "020E", 0, 4);
	/* 17 << 60 == 1 << 60 after the wrap */
	check_memparse(test, "17E", 1ULL << 60, 3);
	/* 1 << 64 wraps to zero for every suffix route */
	check_memparse(test, "16384P", 0, 6);
	check_memparse(test, "16777216T", 0, 9);
	/* largest value that does not wrap for each suffix */
	check_memparse(test, "15E", 0xF000000000000000ULL, 3);
	check_memparse(test, "16383P", 16383ULL << 50, 6);
	/* value that keeps only the low bits after wrapping */
	check_memparse(test, "0xffffffffffffffffK", ULLONG_MAX << 10, 19);
	KUNIT_EXPECT_EQ(test, memparse("0xffffffffffffffffK", NULL),
			0xfffffffffffffc00ULL);
}

/* ---- retptr handling ---- */

static void memparse_retptr_null_test(struct kunit *test)
{
	/* A NULL retptr must be accepted and not affect the result */
	KUNIT_EXPECT_EQ(test, memparse("0", NULL), 0ULL);
	KUNIT_EXPECT_EQ(test, memparse("42", NULL), 42ULL);
	KUNIT_EXPECT_EQ(test, memparse("8K", NULL), 8192ULL);
	KUNIT_EXPECT_EQ(test, memparse("0x100M", NULL), 256ULL << 20);
	KUNIT_EXPECT_EQ(test, memparse("abc", NULL), 0ULL);
	KUNIT_EXPECT_EQ(test, memparse("", NULL), 0ULL);
}

static void memparse_retptr_consumes_suffix_test(struct kunit *test)
{
	const char *s;
	char *end;

	/* a recognised suffix is consumed: retptr is just past it */
	s = "64K";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 64ULL << 10);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 3);
	KUNIT_EXPECT_EQ(test, *end, '\0');

	/* only one suffix char is consumed; further characters remain */
	s = "64KB";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 64ULL << 10);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 3);
	KUNIT_EXPECT_EQ(test, *end, 'B');

	/* a second size suffix is not consumed and not applied */
	s = "1KK";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 1ULL << 10);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 2);
	KUNIT_EXPECT_EQ(test, *end, 'K');

	s = "1MK";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 1ULL << 20);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 2);
	KUNIT_EXPECT_EQ(test, *end, 'K');

	/* digits after a suffix are not re-parsed */
	s = "2M5";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 2ULL << 20);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 2);
	KUNIT_EXPECT_EQ(test, *end, '5');
}

static void memparse_retptr_stops_at_unknown_test(struct kunit *test)
{
	const char *s;
	char *end;

	/* an unrecognised trailing character is not consumed */
	s = "123x";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 123ULL);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 3);
	KUNIT_EXPECT_EQ(test, *end, 'x');

	s = "123,456";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 123ULL);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 3);
	KUNIT_EXPECT_EQ(test, *end, ',');

	s = "123 K";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 123ULL);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 3);
	KUNIT_EXPECT_EQ(test, *end, ' ');

	/* 'B' alone is not a size suffix */
	s = "512B";
	end = NULL;
	KUNIT_EXPECT_EQ(test, memparse(s, &end), 512ULL);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + 3);
	KUNIT_EXPECT_EQ(test, *end, 'B');

	/* letters adjacent to the valid suffixes in the alphabet */
	check_memparse(test, "5J", 5, 1);
	check_memparse(test, "5L", 5, 1);
	check_memparse(test, "5N", 5, 1);
	check_memparse(test, "5F", 5, 1);
	check_memparse(test, "5H", 5, 1);
	check_memparse(test, "5S", 5, 1);
	check_memparse(test, "5U", 5, 1);
	check_memparse(test, "5O", 5, 1);
	check_memparse(test, "5Q", 5, 1);
	check_memparse(test, "5D", 5, 1);
	check_memparse(test, "5j", 5, 1);
	check_memparse(test, "5l", 5, 1);
	check_memparse(test, "5n", 5, 1);
	check_memparse(test, "5f", 5, 1);
	check_memparse(test, "5h", 5, 1);
	check_memparse(test, "5s", 5, 1);
	check_memparse(test, "5u", 5, 1);
	check_memparse(test, "5o", 5, 1);
	check_memparse(test, "5q", 5, 1);
	check_memparse(test, "5d", 5, 1);
}

/* ---- error paths: strings with no number ---- */

static void memparse_empty_string_test(struct kunit *test)
{
	const char *s = "";
	char *end = NULL;

	KUNIT_EXPECT_EQ(test, memparse(s, &end), 0ULL);
	KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s);
}

static void memparse_no_digits_test(struct kunit *test)
{
	/* non-numeric input yields 0 and consumes nothing */
	check_memparse(test, "abc", 0, 0);
	check_memparse(test, "x", 0, 0);
	check_memparse(test, " 1", 0, 0);
	check_memparse(test, "+1", 0, 0);
	check_memparse(test, "-1", 0, 0);
	check_memparse(test, ".5", 0, 0);
	check_memparse(test, "\n1", 0, 0);
}

static void memparse_bare_suffix_test(struct kunit *test)
{
	/*
	 * A suffix with no leading number: the value stays 0, but the suffix
	 * character itself is still consumed.
	 */
	check_memparse(test, "K", 0, 1);
	check_memparse(test, "k", 0, 1);
	check_memparse(test, "M", 0, 1);
	check_memparse(test, "G", 0, 1);
	check_memparse(test, "T", 0, 1);
	check_memparse(test, "P", 0, 1);
	check_memparse(test, "E", 0, 1);
	check_memparse(test, "e", 0, 1);
	check_memparse(test, "KB", 0, 1);
}

static void memparse_hex_prefix_edge_test(struct kunit *test)
{
	/* "0x" with no hex digit afterwards is parsed as octal "0", stop at 'x' */
	check_memparse(test, "0x", 0, 1);
	check_memparse(test, "0X", 0, 1);
	check_memparse(test, "0xg", 0, 1);
	check_memparse(test, "0x ", 0, 1);
	/* "0xK": no hex digit, so '0' octal; 'x' is not a suffix */
	check_memparse(test, "0xK", 0, 1);
	/* "0xE": 'E' is a hex digit, so this is 0xE == 14, no suffix */
	check_memparse(test, "0xE", 14, 3);
	check_memparse(test, "0xe", 14, 3);
	/* "0xEK": hex 0xE then K suffix */
	check_memparse(test, "0xEK", 14ULL << 10, 4);
	/* a lone 'x' is not a prefix */
	check_memparse(test, "x1", 0, 0);
	/* hex digit boundaries: 'g'/'G' are not hex digits */
	check_memparse(test, "0xfg", 15, 3);
	check_memparse(test, "0x1G", 1ULL << 30, 4);
}

static void memparse_truncation_test(struct kunit *test)
{
	/* fractional values are not supported: parsing stops at '.' */
	check_memparse(test, "1.5K", 1, 1);
	check_memparse(test, "1.5", 1, 1);
	/* embedded whitespace terminates the number */
	check_memparse(test, "1 024", 1, 1);
	/* decimal digits followed by a hex-only letter */
	check_memparse(test, "12a", 12, 2);
	check_memparse(test, "12f", 12, 2);
	check_memparse(test, "12A", 12, 2);
}

/* ---- realistic command-line style values ---- */

static void memparse_realistic_values_test(struct kunit *test)
{
	check_memparse(test, "64M", 64ULL << 20, 3);
	check_memparse(test, "128M", 128ULL << 20, 4);
	check_memparse(test, "256m", 256ULL << 20, 4);
	check_memparse(test, "512k", 512ULL << 10, 4);
	check_memparse(test, "2G", 2ULL << 30, 2);
	check_memparse(test, "4g", 4ULL << 30, 2);
	check_memparse(test, "0x1000000", 0x1000000, 9);
	check_memparse(test, "0x10000000M", 0x10000000ULL << 20, 11);
	check_memparse(test, "3072M", 3ULL << 30, 5);
	check_memparse(test, "1536K", 3ULL << 19, 5);

	/* the typical "size@addr" / "size$addr" pattern used by callers */
	{
		const char *s = "64M@0x1000000";
		char *end = NULL;
		unsigned long long size, addr;

		size = memparse(s, &end);
		KUNIT_EXPECT_EQ(test, size, 64ULL << 20);
		KUNIT_ASSERT_PTR_EQ(test, (const char *)end, s + 3);
		KUNIT_EXPECT_EQ(test, *end, '@');
		addr = memparse(end + 1, &end);
		KUNIT_EXPECT_EQ(test, addr, 0x1000000ULL);
		KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + strlen(s));
		KUNIT_EXPECT_EQ(test, *end, '\0');
	}

	/* comma separated list */
	{
		const char *s = "1K,2M,3G";
		char *end = NULL;

		KUNIT_EXPECT_EQ(test, memparse(s, &end), 1ULL << 10);
		KUNIT_ASSERT_EQ(test, *end, ',');
		KUNIT_EXPECT_EQ(test, memparse(end + 1, &end), 2ULL << 20);
		KUNIT_ASSERT_EQ(test, *end, ',');
		KUNIT_EXPECT_EQ(test, memparse(end + 1, &end), 3ULL << 30);
		KUNIT_EXPECT_EQ(test, *end, '\0');
		KUNIT_EXPECT_PTR_EQ(test, (const char *)end, s + strlen(s));
	}
}

/* ---- the input buffer must never be modified ---- */

static void memparse_input_unmodified_test(struct kunit *test)
{
	char buf[] = "0x40M extra";
	char *end = NULL;

	KUNIT_EXPECT_EQ(test, memparse(buf, &end), 0x40ULL << 20);
	KUNIT_EXPECT_PTR_EQ(test, end, buf + 5);
	KUNIT_EXPECT_STREQ(test, buf, "0x40M extra");
}

