	KUNIT_CASE(memparse_hex_test),
	KUNIT_CASE(memparse_octal_test),
	KUNIT_CASE(memparse_suffix_k_test),
	KUNIT_CASE(memparse_suffix_m_test),
	KUNIT_CASE(memparse_suffix_g_test),
	KUNIT_CASE(memparse_suffix_t_test),
	KUNIT_CASE(memparse_suffix_p_test),
