/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for __siphash_aligned() from lib/siphash.c.
 *
 * __siphash_aligned() is only compiled when the architecture does not
 * have efficient unaligned access (see the #ifndef in lib/siphash.c).
 * On architectures that do, siphash() dispatches to __siphash_unaligned(),
 * which implements the exact same SipHash-2-4 algorithm over the same
 * byte stream.  To keep this suite linkable everywhere, the function under
 * test is reached through sip_aligned(), which calls __siphash_aligned()
 * when it exists and otherwise the semantically identical unaligned entry
 * point.  All buffers handed to it are 8-byte aligned either way.
 */

#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/bitops.h>
#include <linux/slab.h>

static u64 sip_aligned(const void *data, size_t len, const siphash_key_t *key)
{
#ifdef CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS
	return __siphash_unaligned(data, len, key);
#else
	return __siphash_aligned(data, len, key);
#endif
}

/*
 * Reference key and vectors from the SipHash reference implementation
 * (https://github.com/veorq/SipHash, vectors.h, SipHash-2-4 64-bit output).
 * Message i is the byte sequence 0x00, 0x01, ..., i-1.
 */
static const siphash_key_t ref_key =
	{{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }};

static const u64 ref_vectors[64] = {
	0x726fdb47dd0e0e31ULL, 0x74f839c593dc67fdULL, 0x0d6c8009d9a94f5aULL,
	0x85676696d7fb7e2dULL, 0xcf2794e0277187b7ULL, 0x18765564cd99a68dULL,
	0xcbc9466e58fee3ceULL, 0xab0200f58b01d137ULL, 0x93f5f5799a932462ULL,
	0x9e0082df0ba9e4b0ULL, 0x7a5dbbc594ddb9f3ULL, 0xf4b32f46226bada7ULL,
