	0x958a324ceb064572ULL
};

static const siphash_key_t alt_key =
	{{ 0xdeadbeefcafebabeULL, 0x0123456789abcdefULL }};

static const siphash_key_t zero_key = {{ 0, 0 }};

#define AGENT_BUF_LEN 256

/* 8-byte aligned scratch buffer holding bytes 0x00, 0x01, 0x02, ... */
struct agent_ctx {
	u8 buf[AGENT_BUF_LEN] __aligned(16);
};

static int agent_test_init(struct kunit *test)
{
	struct agent_ctx *ctx;
	int i;

	ctx = kunit_kzalloc(test, sizeof(*ctx), GFP_KERNEL);
	if (!ctx)
		return -ENOMEM;
	for (i = 0; i < AGENT_BUF_LEN; i++)
		ctx->buf[i] = (u8)i;
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)ctx->buf,
					   SIPHASH_ALIGNMENT));
	test->priv = ctx;
	return 0;
}

/* --- Reference vectors ------------------------------------------------- */

/* Full 0..63 byte sweep against the official SipHash-2-4 test vectors. */
static void agent_test_reference_vectors(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t len;

	for (len = 0; len < ARRAY_SIZE(ref_vectors); len++) {
		KUNIT_EXPECT_EQ_MSG(test, sip_aligned(ctx->buf, len, &ref_key),
				    ref_vectors[len],
				    "reference vector mismatch at len=%zu", len);
	}
}

/* Empty input must still hash (len byte 0 in the final block). */
static void agent_test_empty_input(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	static const u64 dummy __aligned(8) = 0xffffffffffffffffULL;

	KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 0, &ref_key),
			ref_vectors[0]);
	/* With len 0 the data contents must be irrelevant. */
	KUNIT_EXPECT_EQ(test, sip_aligned(&dummy, 0, &ref_key),
			ref_vectors[0]);
	/* Must not match a 1-byte hash of a zero byte. */
	KUNIT_EXPECT_NE(test, sip_aligned(ctx->buf, 0, &ref_key),
			ref_vectors[1]);
}

/* Each of the 1..7 byte tail cases is pinned to a reference value. */
static void agent_test_tail_lengths(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t left;

	for (left = 1; left < sizeof(u64); left++) {
		/* short tail with no full blocks */
		KUNIT_EXPECT_EQ_MSG(test, sip_aligned(ctx->buf, left, &ref_key),
				    ref_vectors[left], "tail %zu (no blocks)",
				    left);
		/* tail after one full block */
		KUNIT_EXPECT_EQ_MSG(test,
				    sip_aligned(ctx->buf, 8 + left, &ref_key),
				    ref_vectors[8 + left],
				    "tail %zu (one block)", left);
		/* tail after several full blocks */
		KUNIT_EXPECT_EQ_MSG(test,
				    sip_aligned(ctx->buf, 56 + left, &ref_key),
				    ref_vectors[56 + left],
				    "tail %zu (seven blocks)", left);
	}
}

/* Exact multiples of the block size have no tail to mix. */
static void agent_test_block_multiples(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t len;

	for (len = 8; len < ARRAY_SIZE(ref_vectors); len += 8) {
		KUNIT_EXPECT_EQ_MSG(test, sip_aligned(ctx->buf, len, &ref_key),
				    ref_vectors[len], "block multiple len=%zu",
				    len);
	}
}

/* --- Equivalence with the fixed-width helpers --------------------------- */

static void agent_test_matches_fixed_width_helpers(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	const __le64 *w = (const __le64 *)ctx->buf;
	const __le32 *d = (const __le32 *)ctx->buf;
	u64 a = le64_to_cpu(w[0]), b = le64_to_cpu(w[1]);
	u64 c = le64_to_cpu(w[2]), e = le64_to_cpu(w[3]);
	const siphash_key_t *keys[] = { &ref_key, &alt_key, &zero_key };
	int i;

	for (i = 0; i < ARRAY_SIZE(keys); i++) {
		const siphash_key_t *k = keys[i];

		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 4, k),
				siphash_1u32(le32_to_cpu(d[0]), k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 8, k),
				siphash_1u64(a, k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 8, k),
				siphash_2u32(le32_to_cpu(d[0]),
					     le32_to_cpu(d[1]), k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 12, k),
				siphash_3u32(le32_to_cpu(d[0]),
					     le32_to_cpu(d[1]),
					     le32_to_cpu(d[2]), k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 16, k),
				siphash_2u64(a, b, k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 16, k),
				siphash_4u32(le32_to_cpu(d[0]),
					     le32_to_cpu(d[1]),
					     le32_to_cpu(d[2]),
					     le32_to_cpu(d[3]), k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 24, k),
				siphash_3u64(a, b, c, k));
		KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 32, k),
				siphash_4u64(a, b, c, e, k));
	}
}

/* Aligned and unaligned entry points must agree byte for byte. */
static void agent_test_matches_unaligned_variant(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	size_t len;

	for (len = 0; len <= AGENT_BUF_LEN; len++) {
		KUNIT_EXPECT_EQ_MSG(test, sip_aligned(ctx->buf, len, &alt_key),
				    __siphash_unaligned(ctx->buf, len, &alt_key),
				    "aligned/unaligned mismatch at len=%zu",
				    len);
	}
}

/* --- Sensitivity: every byte inside [0, len) must matter ---------------- */

static void agent_test_every_byte_affects_hash(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u8 *scratch;
	size_t len, pos;

	scratch = kunit_kzalloc(test, AGENT_BUF_LEN, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, scratch);
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)scratch,
					   SIPHASH_ALIGNMENT));

	for (len = 1; len <= 40; len++) {
		u64 base = sip_aligned(ctx->buf, len, &ref_key);

		for (pos = 0; pos < len; pos++) {
			memcpy(scratch, ctx->buf, AGENT_BUF_LEN);
			scratch[pos] ^= 0x80;
			KUNIT_EXPECT_NE_MSG(test,
					    sip_aligned(scratch, len, &ref_key),
					    base,
					    "byte %zu ignored at len=%zu",
					    pos, len);
		}
	}
}

/* --- Sensitivity: bytes at or beyond len must not matter ----------------- */

static void agent_test_bytes_beyond_len_ignored(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u8 *scratch;
	size_t len, pos;

	scratch = kunit_kzalloc(test, AGENT_BUF_LEN, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, scratch);
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)scratch,
					   SIPHASH_ALIGNMENT));

	for (len = 0; len <= 40; len++) {
		u64 base = sip_aligned(ctx->buf, len, &ref_key);

		/* Corrupt the next 16 bytes one at a time. */
		for (pos = len; pos < len + 16; pos++) {
			memcpy(scratch, ctx->buf, AGENT_BUF_LEN);
			scratch[pos] = ~scratch[pos];
			KUNIT_EXPECT_EQ_MSG(test,
					    sip_aligned(scratch, len, &ref_key),
					    base,
					    "byte %zu leaked into len=%zu",
					    pos, len);
		}
		/* And all of them at once, with 0xff fill. */
		memcpy(scratch, ctx->buf, len);
		memset(scratch + len, 0xff, AGENT_BUF_LEN - len);
		KUNIT_EXPECT_EQ_MSG(test, sip_aligned(scratch, len, &ref_key),
				    base, "trailing 0xff leaked at len=%zu",
				    len);
	}
}

/* --- Length is part of the hash ------------------------------------------ */

/* A zero-padded prefix must not collide with the shorter message. */
static void agent_test_length_is_mixed_in(struct kunit *test)
{
	u8 *zeros;
	size_t len;
	u64 prev;

	zeros = kunit_kzalloc(test, AGENT_BUF_LEN, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, zeros);
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)zeros,
					   SIPHASH_ALIGNMENT));

	prev = sip_aligned(zeros, 0, &ref_key);
	for (len = 1; len <= 64; len++) {
		u64 cur = sip_aligned(zeros, len, &ref_key);

		KUNIT_EXPECT_NE_MSG(test, cur, prev,
				    "len %zu and %zu of zeros collide",
				    len - 1, len);
		prev = cur;
	}

	/* Across the 7/8 and 8/9 boundaries specifically. */
	KUNIT_EXPECT_NE(test, sip_aligned(zeros, 7, &ref_key),
			sip_aligned(zeros, 8, &ref_key));
	KUNIT_EXPECT_NE(test, sip_aligned(zeros, 8, &ref_key),
			sip_aligned(zeros, 9, &ref_key));
	KUNIT_EXPECT_NE(test, sip_aligned(zeros, 15, &ref_key),
			sip_aligned(zeros, 16, &ref_key));
}

/* --- Key handling --------------------------------------------------------- */

static void agent_test_key_sensitivity(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t swapped = {{ ref_key.key[1], ref_key.key[0] }};
	siphash_key_t k0 = {{ ref_key.key[0], 0 }};
	siphash_key_t k1 = {{ 0, ref_key.key[1] }};
	siphash_key_t onebit = {{ 0, 0 }};
	size_t len;
	int bit;

	for (len = 0; len <= 20; len++) {
		u64 base = sip_aligned(ctx->buf, len, &ref_key);

		KUNIT_EXPECT_NE_MSG(test, base,
				    sip_aligned(ctx->buf, len, &alt_key),
				    "alt key collides at len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, base,
				    sip_aligned(ctx->buf, len, &zero_key),
				    "zero key collides at len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, base,
				    sip_aligned(ctx->buf, len, &swapped),
				    "swapped key halves collide at len=%zu",
				    len);
		KUNIT_EXPECT_NE_MSG(test, base,
				    sip_aligned(ctx->buf, len, &k0),
				    "key[1] ignored at len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, base,
				    sip_aligned(ctx->buf, len, &k1),
				    "key[0] ignored at len=%zu", len);
	}

	/* Every single key bit must influence the output. */
	for (bit = 0; bit < 128; bit++) {
		onebit.key[0] = bit < 64 ? BIT_ULL(bit) : 0;
		onebit.key[1] = bit >= 64 ? BIT_ULL(bit - 64) : 0;
		KUNIT_EXPECT_NE_MSG(test, sip_aligned(ctx->buf, 13, &onebit),
				    sip_aligned(ctx->buf, 13, &zero_key),
				    "key bit %d ignored", bit);
	}
}

/* Zero key is a legitimate key, not an error. */
static void agent_test_zero_key_is_valid(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;

	KUNIT_EXPECT_TRUE(test, siphash_key_is_zero(&zero_key));
	KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 0, &zero_key),
			sip_aligned(ctx->buf, 0, &zero_key));
	KUNIT_EXPECT_NE(test, sip_aligned(ctx->buf, 0, &zero_key), 0ULL);
	KUNIT_EXPECT_EQ(test, sip_aligned(ctx->buf, 8, &zero_key),
			siphash_1u64(le64_to_cpu(*(const __le64 *)ctx->buf),
				     &zero_key));
}

/* --- Determinism and location independence -------------------------------- */

static void agent_test_deterministic_and_position_independent(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u8 *copy;
	size_t len, off;

	copy = kunit_kzalloc(test, 2 * AGENT_BUF_LEN, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, copy);

	for (len = 0; len <= 33; len++) {
		u64 base = sip_aligned(ctx->buf, len, &alt_key);

		/* Same call twice. */
		KUNIT_EXPECT_EQ(test, base, sip_aligned(ctx->buf, len, &alt_key));

		/* Same bytes at other 8-byte aligned addresses. */
		for (off = 0; off <= 64; off += 8) {
			memcpy(copy + off, ctx->buf, len);
			KUNIT_EXPECT_EQ_MSG(test,
					    sip_aligned(copy + off, len,
							&alt_key),
					    base,
					    "len=%zu differs at offset %zu",
					    len, off);
		}
	}
}

/* --- Large inputs ---------------------------------------------------------- */

static void agent_test_large_input(struct kunit *test)
{
	u8 *big;
	size_t len, i;
	const size_t big_len = 4096 + 7;

	big = kunit_kzalloc(test, big_len + 16, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, big);
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)big,
					   SIPHASH_ALIGNMENT));
	for (i = 0; i < big_len + 16; i++)
		big[i] = (u8)(i * 7 + 3);

	for (len = big_len - 8; len <= big_len; len++) {
		u64 h = sip_aligned(big, len, &ref_key);

		KUNIT_EXPECT_EQ_MSG(test, h,
				    __siphash_unaligned(big, len, &ref_key),
				    "large len=%zu mismatch", len);
		KUNIT_EXPECT_NE_MSG(test, h,
				    sip_aligned(big, len - 1, &ref_key),
				    "large len=%zu equals len-1", len);
	}

	/* Last byte of a large odd-length message must still matter. */
	{
		u64 before = sip_aligned(big, big_len, &ref_key);

		big[big_len - 1] ^= 0x01;
		KUNIT_EXPECT_NE(test, before, sip_aligned(big, big_len, &ref_key));
		/* First byte beyond the end must not. */
		big[big_len - 1] ^= 0x01;
		big[big_len] ^= 0xff;
		KUNIT_EXPECT_EQ(test, before, sip_aligned(big, big_len, &ref_key));
	}
}

/* Hash of the same 8-byte block repeated differs with block count. */
static void agent_test_repeated_blocks(struct kunit *test)
{
	u64 *blocks;
	size_t n;
	u64 prev;

	blocks = kunit_kzalloc(test, 16 * sizeof(u64), GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, blocks);
	for (n = 0; n < 16; n++)
		blocks[n] = 0x0123456789abcdefULL;

	prev = sip_aligned(blocks, 0, &ref_key);
	for (n = 1; n <= 16; n++) {
		u64 cur = sip_aligned(blocks, n * sizeof(u64), &ref_key);

		KUNIT_EXPECT_NE_MSG(test, cur, prev, "%zu blocks collide",
				    n);
		prev = cur;
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_reference_vectors),
	KUNIT_CASE(agent_test_empty_input),
	KUNIT_CASE(agent_test_tail_lengths),
	KUNIT_CASE(agent_test_block_multiples),
	KUNIT_CASE(agent_test_matches_fixed_width_helpers),
	KUNIT_CASE(agent_test_matches_unaligned_variant),
	KUNIT_CASE(agent_test_every_byte_affects_hash),
	KUNIT_CASE(agent_test_bytes_beyond_len_ignored),
	KUNIT_CASE(agent_test_length_is_mixed_in),
	KUNIT_CASE(agent_test_key_sensitivity),
	KUNIT_CASE(agent_test_zero_key_is_valid),
	KUNIT_CASE(agent_test_deterministic_and_position_independent),
	KUNIT_CASE(agent_test_large_input),
	KUNIT_CASE(agent_test_repeated_blocks),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.init = agent_test_init,
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

