// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for __hsiphash_aligned() in lib/siphash.c.
 *
 * __hsiphash_aligned() is only compiled when the architecture does not
 * have CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS (otherwise hsiphash()
 * always dispatches to __hsiphash_unaligned(), and the aligned symbol
 * does not exist).  On such configs we exercise __hsiphash_unaligned()
 * through the same wrapper so that the file still links and the suite
 * still validates the identical algorithm and contract.
 */

#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/bitops.h>
#include <linux/module.h>
#include <linux/unaligned.h>

#ifndef CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS
#define HSIP_ALIGNED_UNDER_TEST	__hsiphash_aligned
#else
#define HSIP_ALIGNED_UNDER_TEST	__hsiphash_unaligned
#endif

static u32 hsip_aligned(const void *data, size_t len, const hsiphash_key_t *key)
{
	return HSIP_ALIGNED_UNDER_TEST(data, len, key);
}

/*
 * Reference vectors (from the upstream SipHash reference implementation,
 * as used by lib/siphash_kunit.c). Vector [i] is the hash of the bytes
 * 0, 1, ..., i-1 under the test key.  On 64-bit, HalfSipHash1-3 is really
 * SipHash1-3 with a truncated result; on 32-bit it is HalfSipHash1-3.
 */
#if BITS_PER_LONG == 64
static const hsiphash_key_t agent_test_key =
	{{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }};

static const u32 agent_test_vectors[64] = {
	0x050fc4dcU, 0x7d57ca93U, 0x4dc7d44dU,
	0xe7ddf7fbU, 0x88d38328U, 0x49533b67U,
	0xc59f22a7U, 0x9bb11140U, 0x8d299a8eU,
	0x6c063de4U, 0x92ff097fU, 0xf94dc352U,
	0x57b4d9a2U, 0x1229ffa7U, 0xc0f95d34U,
	0x2a519956U, 0x7d908b66U, 0x63dbd80cU,
