#define AGENT_BUF_LEN	256

/* Deterministic pseudo-random fill so failures are reproducible. */
static void agent_fill(u8 *buf, size_t len, u32 seed)
{
	size_t i;

	for (i = 0; i < len; i++) {
		seed = seed * 1103515245U + 12345U;
		buf[i] = seed >> 16;
	}
}

/* 1. Known-answer test for every length 0..63 on an aligned buffer. */
static void agent_hsiphash_aligned_vectors(struct kunit *test)
{
	u8 in[64] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int i;

	for (i = 0; i < 64; i++)
		in[i] = i;

	for (i = 0; i < 64; i++)
		KUNIT_EXPECT_EQ_MSG(test,
				    hsip_aligned(in, i, &agent_test_key),
				    agent_test_vectors[i],
				    "known-answer mismatch at len %u", i);
}

/* 2. Zero length: a valid, well-defined input that touches no data byte. */
static void agent_hsiphash_aligned_zero_len(struct kunit *test)
{
	u8 in[16] __aligned(HSIPHASH_ALIGNMENT);
	u32 h_zero, h_ff;

	memset(in, 0x00, sizeof(in));
	h_zero = hsip_aligned(in, 0, &agent_test_key);
	memset(in, 0xff, sizeof(in));
	h_ff = hsip_aligned(in, 0, &agent_test_key);

	/* Buffer contents must be irrelevant when len == 0. */
	KUNIT_EXPECT_EQ(test, h_zero, h_ff);
	KUNIT_EXPECT_EQ(test, h_zero, agent_test_vectors[0]);
	/* And it must not collide with the hash of a single zero byte. */
	memset(in, 0x00, sizeof(in));
	KUNIT_EXPECT_NE(test, h_zero, hsip_aligned(in, 1, &agent_test_key));
}

/* 3. Must agree with the fixed-width helpers at 4, 8, 12 and 16 bytes. */
static void agent_hsiphash_aligned_matches_nu32(struct kunit *test)
{
	u8 in[16] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int i;
	u32 w[4];

	for (i = 0; i < 16; i++)
		in[i] = 0xa0 + i * 7;
	for (i = 0; i < 4; i++)
		w[i] = get_unaligned_le32(in + 4 * i);

	KUNIT_EXPECT_EQ(test, hsip_aligned(in, 4, &agent_test_key),
			hsiphash_1u32(w[0], &agent_test_key));
	KUNIT_EXPECT_EQ(test, hsip_aligned(in, 8, &agent_test_key),
			hsiphash_2u32(w[0], w[1], &agent_test_key));
	KUNIT_EXPECT_EQ(test, hsip_aligned(in, 12, &agent_test_key),
			hsiphash_3u32(w[0], w[1], w[2], &agent_test_key));
	KUNIT_EXPECT_EQ(test, hsip_aligned(in, 16, &agent_test_key),
			hsiphash_4u32(w[0], w[1], w[2], w[3], &agent_test_key));

	/* And the reference vectors agree with the helpers too. */
	KUNIT_EXPECT_EQ(test, hsiphash_1u32(0x03020100U, &agent_test_key),
			agent_test_vectors[4]);
	KUNIT_EXPECT_EQ(test, hsiphash_2u32(0x03020100U, 0x07060504U,
					    &agent_test_key),
			agent_test_vectors[8]);
	KUNIT_EXPECT_EQ(test, hsiphash_3u32(0x03020100U, 0x07060504U,
					    0x0b0a0908U, &agent_test_key),
			agent_test_vectors[12]);
	KUNIT_EXPECT_EQ(test, hsiphash_4u32(0x03020100U, 0x07060504U,
					    0x0b0a0908U, 0x0f0e0d0cU,
					    &agent_test_key),
			agent_test_vectors[16]);
}

/* 4. Must agree with __hsiphash_unaligned on the same aligned data. */
static void agent_hsiphash_aligned_matches_unaligned(struct kunit *test)
{
	u8 in[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	size_t len;

	agent_fill(in, sizeof(in), 0x1234abcdU);

	for (len = 0; len <= sizeof(in); len++)
		KUNIT_EXPECT_EQ_MSG(test,
				    hsip_aligned(in, len, &agent_test_key),
				    __hsiphash_unaligned(in, len,
							 &agent_test_key),
				    "aligned/unaligned disagree at len %zu",
				    len);
}

/*
 * 5. Every byte inside [0, len) must influence the result, and the byte
 *    at index len (just past the end) must not.  Catches tail handling
 *    that reads one byte too few or too many for any value of len % 8.
 */
static void agent_hsiphash_aligned_byte_sensitivity(struct kunit *test)
{
	u8 in[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	size_t len, pos;
	u32 base, h;

	for (len = 0; len < 72; len++) {
		agent_fill(in, sizeof(in), 0x5eed0000U + len);
		base = hsip_aligned(in, len, &agent_test_key);

		for (pos = 0; pos < len; pos++) {
			in[pos] ^= 0x01;
			h = hsip_aligned(in, len, &agent_test_key);
			in[pos] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test, base, h,
					    "byte %zu ignored at len %zu",
					    pos, len);

			in[pos] ^= 0x80;
			h = hsip_aligned(in, len, &agent_test_key);
			in[pos] ^= 0x80;
			KUNIT_EXPECT_NE_MSG(test, base, h,
					    "high bit of byte %zu ignored at len %zu",
					    pos, len);
		}

		/* Bytes beyond the end must have no effect. */
		in[len] ^= 0xff;
		h = hsip_aligned(in, len, &agent_test_key);
		in[len] ^= 0xff;
		KUNIT_EXPECT_EQ_MSG(test, base, h,
				    "byte past end read at len %zu", len);

		in[len + 1] ^= 0xff;
		h = hsip_aligned(in, len, &agent_test_key);
		in[len + 1] ^= 0xff;
		KUNIT_EXPECT_EQ_MSG(test, base, h,
				    "byte len+1 read at len %zu", len);
	}
}

/*
 * 6. The length is part of the input: a buffer of length n must hash
 *    differently from the same bytes followed by a zero (length n+1),
 *    even though the extra byte contributes zero bits of data.
 */
static void agent_hsiphash_aligned_length_encoding(struct kunit *test)
{
	u8 in[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	size_t len;

	memset(in, 0, sizeof(in));
	for (len = 0; len < 72; len++)
		KUNIT_EXPECT_NE_MSG(test,
				    hsip_aligned(in, len, &agent_test_key),
				    hsip_aligned(in, len + 1, &agent_test_key),
				    "zero-padded len %zu collides with len %zu",
				    len, len + 1);

	/* Same, with all-0xff data: longer input must still differ. */
	memset(in, 0xff, sizeof(in));
	for (len = 0; len < 72; len++)
		KUNIT_EXPECT_NE_MSG(test,
				    hsip_aligned(in, len, &agent_test_key),
				    hsip_aligned(in, len + 1, &agent_test_key),
				    "0xff len %zu collides with len %zu",
				    len, len + 1);
}

/* 7. Byte order within a word matters (little-endian loads, not swaps). */
static void agent_hsiphash_aligned_byte_order(struct kunit *test)
{
	u8 in[16] __aligned(HSIPHASH_ALIGNMENT);
	size_t len, a, b;
	u32 base, h;
	u8 tmp;

	for (len = 2; len <= 16; len++) {
		for (a = 0; a < len; a++)
			in[a] = 0x10 + a;
		base = hsip_aligned(in, len, &agent_test_key);

		for (a = 0; a < len; a++) {
			for (b = a + 1; b < len; b++) {
				tmp = in[a]; in[a] = in[b]; in[b] = tmp;
				h = hsip_aligned(in, len, &agent_test_key);
				tmp = in[a]; in[a] = in[b]; in[b] = tmp;
				KUNIT_EXPECT_NE_MSG(test, base, h,
						    "swap %zu<->%zu invisible at len %zu",
						    a, b, len);
			}
		}
	}
}

/* 8. Both halves of the key must be used, and keys must be distinct. */
static void agent_hsiphash_aligned_key_sensitivity(struct kunit *test)
{
	u8 in[24] __aligned(HSIPHASH_ALIGNMENT);
	hsiphash_key_t k0 = {{ 0, 0 }};
	hsiphash_key_t k1 = {{ 1, 0 }};
	hsiphash_key_t k2 = {{ 0, 1 }};
	hsiphash_key_t k3 = {{ 1, 1 }};
	hsiphash_key_t kswap;
	size_t len;
	u32 h0, h1, h2, h3;

	agent_fill(in, sizeof(in), 0xdeadbeefU);

	for (len = 0; len <= sizeof(in); len++) {
		h0 = hsip_aligned(in, len, &k0);
		h1 = hsip_aligned(in, len, &k1);
		h2 = hsip_aligned(in, len, &k2);
		h3 = hsip_aligned(in, len, &k3);
		KUNIT_EXPECT_NE_MSG(test, h0, h1, "key[0] ignored at len %zu", len);
		KUNIT_EXPECT_NE_MSG(test, h0, h2, "key[1] ignored at len %zu", len);
		KUNIT_EXPECT_NE_MSG(test, h1, h2, "key halves interchangeable at len %zu", len);
		KUNIT_EXPECT_NE_MSG(test, h0, h3, "key ignored at len %zu", len);
	}

	/* Swapping key halves must change the output. */
	kswap.key[0] = agent_test_key.key[1];
	kswap.key[1] = agent_test_key.key[0];
	KUNIT_EXPECT_NE(test, hsip_aligned(in, 16, &agent_test_key),
			hsip_aligned(in, 16, &kswap));

	/* Flipping each key bit (within 32 bits, valid on both widths). */
	for (len = 0; len < 32; len++) {
		hsiphash_key_t k = agent_test_key;

		k.key[0] ^= 1UL << len;
		KUNIT_EXPECT_NE_MSG(test, hsip_aligned(in, 13, &agent_test_key),
				    hsip_aligned(in, 13, &k),
				    "key[0] bit %zu ignored", len);
		k = agent_test_key;
		k.key[1] ^= 1UL << len;
		KUNIT_EXPECT_NE_MSG(test, hsip_aligned(in, 13, &agent_test_key),
				    hsip_aligned(in, 13, &k),
				    "key[1] bit %zu ignored", len);
	}
}

/* 9. Pure function: same input, same output; input never modified. */
static void agent_hsiphash_aligned_deterministic(struct kunit *test)
{
	u8 in[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	u8 copy[AGENT_BUF_LEN];
	hsiphash_key_t key = agent_test_key;
	size_t len;
	u32 h1, h2;

	agent_fill(in, sizeof(in), 0x0badf00dU);
	memcpy(copy, in, sizeof(in));

	for (len = 0; len <= sizeof(in); len += 7) {
		h1 = hsip_aligned(in, len, &key);
		h2 = hsip_aligned(in, len, &key);
		KUNIT_EXPECT_EQ_MSG(test, h1, h2, "nondeterministic at len %zu", len);
	}

	KUNIT_EXPECT_EQ(test, memcmp(in, copy, sizeof(in)), 0);
	KUNIT_EXPECT_EQ(test, key.key[0], agent_test_key.key[0]);
	KUNIT_EXPECT_EQ(test, key.key[1], agent_test_key.key[1]);
}

/*
 * 10. Long inputs: many full blocks plus every possible tail length.
 *     The result must depend on the first block, the last full block,
 *     and every tail byte, and must match the unaligned implementation.
 */
static void agent_hsiphash_aligned_long_input(struct kunit *test)
{
	u8 in[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	size_t len, pos;
	u32 base, h;

	for (len = AGENT_BUF_LEN - 16; len <= AGENT_BUF_LEN; len++) {
		agent_fill(in, sizeof(in), 0x10000000U + len);
		base = hsip_aligned(in, len, &agent_test_key);

		KUNIT_EXPECT_EQ_MSG(test, base,
				    __hsiphash_unaligned(in, len, &agent_test_key),
				    "long input mismatch at len %zu", len);

		/* first byte */
		in[0] ^= 0x55;
		h = hsip_aligned(in, len, &agent_test_key);
		in[0] ^= 0x55;
		KUNIT_EXPECT_NE_MSG(test, base, h, "first byte ignored at len %zu", len);

		/* every byte of the last 16 */
		for (pos = len - 16; pos < len; pos++) {
			in[pos] ^= 0x55;
			h = hsip_aligned(in, len, &agent_test_key);
			in[pos] ^= 0x55;
			KUNIT_EXPECT_NE_MSG(test, base, h,
					    "byte %zu ignored at len %zu", pos, len);
		}

		/* and nothing beyond */
		if (len < AGENT_BUF_LEN) {
			in[len] ^= 0x55;
			h = hsip_aligned(in, len, &agent_test_key);
			in[len] ^= 0x55;
			KUNIT_EXPECT_EQ_MSG(test, base, h,
					    "byte past end read at len %zu", len);
		}
	}
}

/* 11. Prefix property: hash of len n depends only on the first n bytes. */
static void agent_hsiphash_aligned_prefix_only(struct kunit *test)
{
	u8 a[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	u8 b[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	size_t len;

	agent_fill(a, sizeof(a), 0x11111111U);
	agent_fill(b, sizeof(b), 0x22222222U);

	for (len = 0; len <= 80; len++) {
		/* Make b agree with a on the first len bytes only. */
		memcpy(b, a, len);
		KUNIT_EXPECT_EQ_MSG(test,
				    hsip_aligned(a, len, &agent_test_key),
				    hsip_aligned(b, len, &agent_test_key),
				    "trailing garbage affects len %zu", len);
		if (len < sizeof(b)) {
			/* b differs from a at index len. */
			b[len] = a[len] ^ 0xff;
			KUNIT_EXPECT_NE_MSG(test,
					    hsip_aligned(a, len + 1, &agent_test_key),
					    hsip_aligned(b, len + 1, &agent_test_key),
					    "last byte ignored at len %zu", len + 1);
		}
		agent_fill(b, sizeof(b), 0x22222222U);
	}
}

/* 12. Reference vectors for distinct inputs are themselves distinct. */
static void agent_hsiphash_aligned_no_trivial_collisions(struct kunit *test)
{
	u8 in[AGENT_BUF_LEN] __aligned(HSIPHASH_ALIGNMENT);
	u32 hashes[AGENT_BUF_LEN + 1];
	size_t i, j;

	for (i = 0; i < 64; i++)
		for (j = i + 1; j < 64; j++)
			KUNIT_EXPECT_NE_MSG(test, agent_test_vectors[i],
					    agent_test_vectors[j],
					    "vectors %zu and %zu collide", i, j);

	/* Zero buffer of every length 0..256 must hash to distinct values. */
	memset(in, 0, sizeof(in));
	for (i = 0; i <= AGENT_BUF_LEN; i++)
		hashes[i] = hsip_aligned(in, i, &agent_test_key);
	for (i = 0; i <= AGENT_BUF_LEN; i++)
		for (j = i + 1; j <= AGENT_BUF_LEN; j++)
			KUNIT_EXPECT_NE_MSG(test, hashes[i], hashes[j],
					    "zero buffers of len %zu and %zu collide",
					    i, j);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_hsiphash_aligned_vectors),
	KUNIT_CASE(agent_hsiphash_aligned_zero_len),
	KUNIT_CASE(agent_hsiphash_aligned_matches_nu32),
	KUNIT_CASE(agent_hsiphash_aligned_matches_unaligned),
	KUNIT_CASE(agent_hsiphash_aligned_byte_sensitivity),
	KUNIT_CASE(agent_hsiphash_aligned_length_encoding),
	KUNIT_CASE(agent_hsiphash_aligned_byte_order),
	KUNIT_CASE(agent_hsiphash_aligned_key_sensitivity),
	KUNIT_CASE(agent_hsiphash_aligned_deterministic),
	KUNIT_CASE(agent_hsiphash_aligned_long_input),
	KUNIT_CASE(agent_hsiphash_aligned_prefix_only),
	KUNIT_CASE(agent_hsiphash_aligned_no_trivial_collisions),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

